window.WORD_AI_EXAMPLE_CHUNK = {"entries":{"contact":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"联系"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"联系"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"接触"}],"examples":[{"sentence":"Please leave a contact number so that the clinic can confirm your appointment.","translation":"请留下联系电话，以便诊所确认你的预约。","targetForm":"contact","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Regular contact with tutors helps distance learners remain motivated throughout the course.","translation":"与辅导老师保持经常联系，有助于远程学习者在整个课程中保持动力。","targetForm":"contact","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The company contacted affected customers as soon as the data problem was discovered.","translation":"公司一发现数据问题，就联系了受影响的客户。","targetForm":"contacted","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Researchers made contact with coastal communities before designing the survey.","translation":"研究人员在设计调查问卷前与沿海社区取得了联系。","targetForm":"contact","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Direct contact between local officials and residents can prevent small disputes from growing.","translation":"地方官员与居民直接接触，可以防止小矛盾不断扩大。","targetForm":"contact","senseId":"source-n-4","sourceSenseId":"n-4"}]},"compromise":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"折中方案"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"妥协处理"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"折中"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"危害"}],"examples":[{"sentence":"The final agreement was a compromise that protected public access while allowing the project to proceed.","translation":"最终协议是一项折中方案；它保护了公众使用权，同时允许项目继续推进。","targetForm":"compromise","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"After weeks of negotiation, both sides compromised on a timetable that neither considered ideal.","translation":"经过数周谈判，双方就在一个双方都不认为理想的时间表上作出了妥协。","targetForm":"compromised","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"A compromise between speed and accuracy is sometimes necessary, but it should be explained openly.","translation":"速度与准确性之间有时需要折中，但这种折中应被公开说明。","targetForm":"compromise","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Sharing passwords compromises security because it becomes impossible to trace who changed sensitive information.","translation":"共享密码会损害安全性，因为这样就无法追踪是谁更改了敏感信息。","targetForm":"compromises","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"By compromising on minor details, the committee preserved the principle that mattered most to both groups.","translation":"委员会在次要细节上让步，从而保留了双方最重视的原则。","targetForm":"compromising","senseId":"source-v-1","sourceSenseId":"v-1"}]},"comply":{"senseGroups":[{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"[法] 遵守","contextReviewed":true},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"依从"},{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"承诺","contextReviewed":true},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"顺从"}],"examples":[{"sentence":"All contractors must comply with safety rules before they are allowed to begin work on the site.","translation":"所有承包商必须在获准开工前遵守安全规定。","targetForm":"comply","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"The company complies with the new standard by publishing details of how customer data are protected.","translation":"该公司通过公布客户数据如何受到保护的细节来遵守新标准。","targetForm":"complies","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"Applicants who complied with the instructions were processed quickly, whereas incomplete forms required further checks.","translation":"遵守说明的申请者很快得到处理，而表格不完整者需要进一步核查。","targetForm":"complied","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"By complying with the request, the agency committed itself to sharing the evidence behind the final decision.","translation":"通过遵从这项请求，该机构承诺分享最终决定背后的证据。","targetForm":"complying","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"Citizens are more likely to comply when rules are explained clearly and applied consistently.","translation":"当规则被清楚说明并得到一致执行时，公民更可能遵从。","targetForm":"comply","senseId":"source-v-1","sourceSenseId":"v-1"}]},"courtesy":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"礼貌"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"好意"}],"examples":[{"sentence":"If researchers do not observe the courtesy of obtaining informed consent, their study risks ethical and legal repercussions.","translation":"如果研究人员不遵守获取知情同意的礼节，他们的研究可能面临伦理和法律后果。","targetForm":"courtesy","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The conference organizers provided simultaneous interpretation as a courtesy to international attendees, thereby fostering inclusive dialogue.","translation":"会议组织者提供同声传译作为对国际与会者的礼遇，从而促进了包容性对话。","targetForm":"courtesy","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"While digital communication often lacks nuance, a simple courtesy such as acknowledging receipt of an email can prevent misunderstandings.","translation":"虽然数字通信往往缺乏细微之处，但像确认收到邮件这样的简单礼貌可以避免误解。","targetForm":"courtesy","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the interview was highly competitive, the panel treated every candidate with professional courtesy.","translation":"尽管面试竞争非常激烈，评审小组仍以专业的礼貌对待每一位候选人。","targetForm":"courtesy","senseId":"source-n-1","sourceSenseId":"n-1"}]},"compassion":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"同情"}],"examples":[{"sentence":"The volunteer spoke with compassion, which helped the visitor explain a difficult situation without feeling judged.","translation":"志愿者带着同情心交谈，这帮助来访者在不感到被评判的情况下说明困难处境。","targetForm":"compassion","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the policy was strict, the staff applied it with compassion when families faced unexpected hardship.","translation":"尽管政策严格，工作人员在家庭遭遇意外困难时仍带着同情执行。","targetForm":"compassion","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The novel invites readers to consider whether compassion can coexist with the need for clear public rules.","translation":"这部小说邀请读者思考，同情心能否与明确的公共规则共存。","targetForm":"compassion","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because the teacher showed compassion without lowering expectations, the student felt supported while continuing to improve.","translation":"由于老师表现出同情而不降低期望，学生感到被支持，同时继续进步。","targetForm":"compassion","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Public compassion often becomes visible when neighbours organise practical help after a sudden local emergency.","translation":"当地社区发生突发紧急情况后，邻居组织实际帮助时，公众的同情心往往会显现。","targetForm":"compassion","senseId":"source-n-1","sourceSenseId":"n-1"}]},"copyright":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"版权"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"著作权"}],"examples":[{"sentence":"Although digital technology has made copying effortless, copyright remains essential for protecting the economic interests of content creators.","translation":"尽管数字技术使复制变得毫不费力，但版权对于保护内容创作者的经济利益仍然至关重要。","targetForm":"copyright","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The court ruled that the defendant had infringed copyright by reproducing substantial portions of the novel without permission.","translation":"法院裁定，被告未经许可复制了小说的实质性部分，侵犯了版权。","targetForm":"copyright","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Educational institutions must navigate complex copyright regulations when they digitize library collections for remote learning.","translation":"教育机构在为远程学习数字化图书馆馆藏时，必须应对复杂的版权法规。","targetForm":"copyright","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because copyright law grants creators exclusive rights for a limited time, it provides an incentive for artists to produce original works.","translation":"由于版权法在有限时间内赋予创作者专有权利，它激励艺术家创作原创作品。","targetForm":"copyright","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Scholars who publish in open-access journals often retain copyright, which allows them to share their work freely with colleagues around the world.","translation":"在开放获取期刊上发表论文的学者通常保留版权，这使他们能够与世界各地的同事自由分享研究成果。","targetForm":"copyright","senseId":"source-n-1","sourceSenseId":"n-1"}]},"cooperate":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"合作"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"配合"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"协力"}],"examples":[{"sentence":"When research institutions cooperate across borders, they can pool resources and accelerate scientific breakthroughs.","translation":"当研究机构跨越国界合作时，它们可以汇集资源并加速科学突破。","targetForm":"cooperate","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Local communities must cooperate with environmental agencies so that the region's biodiversity can be protected for future generations.","translation":"当地社区必须与环保机构合作，才能为后代保护该地区的生物多样性。","targetForm":"cooperate","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Because employees are more likely to cooperate when they feel genuinely heard, transparent communication is essential.","translation":"由于员工感到自己被真正倾听时更愿意配合，透明沟通至关重要。","targetForm":"cooperate","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"To address the water crisis, several governments cooperated on irrigation technology rather than pursuing isolated solutions.","translation":"为应对水资源危机，多个政府在灌溉技术上开展了合作，而不是各自寻求孤立的解决办法。","targetForm":"cooperated","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Although the two departments have different priorities, they are cooperating to deliver the project without sacrificing quality.","translation":"尽管这两个部门的优先事项不同，它们仍在合作推进项目，并且不牺牲质量。","targetForm":"cooperating","senseId":"source-v-1","sourceSenseId":"v-1"}]},"commonplace":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"寻常事"}],"examples":[{"sentence":"The use of artificial intelligence in daily life is becoming a commonplace, which raises important ethical questions.","translation":"人工智能在日常生活中的使用正变得司空见惯，这引发了重要的伦理问题。","targetForm":"commonplace","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although online shopping is now a commonplace, it has profoundly transformed consumer behavior and retail industries.","translation":"尽管网上购物如今已是寻常事，但它深刻地改变了消费者行为和零售业。","targetForm":"commonplace","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"While electric cars were once a novelty, they have become a commonplace in many cities due to environmental concerns.","translation":"尽管电动汽车曾经是新奇事物，但由于环境问题，它们已在许多城市变得司空见惯。","targetForm":"commonplace","senseId":"source-n-1","sourceSenseId":"n-1"}]},"constitute":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"构成"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"组成"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"任命"}],"examples":[{"sentence":"The diverse cultural backgrounds of the employees constitute a valuable asset for the multinational corporation.","translation":"员工多元的文化背景构成了这家跨国公司的一笔宝贵财富。","targetForm":"constitute","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"These four fundamental principles constitute the theoretical framework upon which the entire argument is built.","translation":"这四项基本原则构成了整个论证所依据的理论框架。","targetForm":"constitute","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The committee was constituted last month to address the urgent environmental concerns raised by the community.","translation":"该委员会于上月成立，旨在解决社区提出的紧迫环境问题。","targetForm":"constituted","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"A single molecule of water is constituted by two hydrogen atoms and one oxygen atom.","translation":"一个水分子由两个氢原子和一个氧原子构成。","targetForm":"constituted","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The board of directors formally constituted her as the chief executive officer after a unanimous vote.","translation":"董事会经一致投票后正式任命她为首席执行官。","targetForm":"constituted","senseId":"source-v-3","sourceSenseId":"v-3"}]},"comrade":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"伙伴"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"同志"}],"examples":[{"sentence":"The old soldier often spoke of his fallen comrades with a mixture of pride and sorrow.","translation":"这位老兵常常带着自豪与悲伤交织的情感谈起他牺牲的战友们。","targetForm":"comrades","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"In the laboratory, she found a comrade who shared her passion for molecular biology.","translation":"在实验室里，她找到了一位与她同样热爱分子生物学的伙伴。","targetForm":"comrade","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The political activist addressed his comrades at the rally, urging them to remain steadfast.","translation":"这位政治活动家在集会上向同志们讲话，敦促他们保持坚定。","targetForm":"comrades","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"After years of working together, they had become more than colleagues; they were trusted comrades.","translation":"经过多年的共事，他们已不仅仅是同事，而是值得信赖的伙伴。","targetForm":"comrades","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The mountaineer relied on his comrade to navigate the treacherous ice field safely.","translation":"这位登山者依靠他的伙伴安全地穿越了危险的冰原。","targetForm":"comrade","senseId":"source-n-2","sourceSenseId":"n-2"}]},"coordinate":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"坐标"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"并列的"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"(使)协调"}],"examples":[{"sentence":"Before setting out, the climbers checked the map coordinate of the shelter and shared it with the guide.","translation":"出发前，登山者核对了避难处的地图坐标，并把它告知向导。","targetForm":"coordinate","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The survey team recorded each coordinate carefully so that another group could locate the same water source.","translation":"测量队认真记录每个坐标，以便另一组人也能找到同一处水源。","targetForm":"coordinate","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"In the phrase 'a calm and thoughtful response,' calm and thoughtful are coordinate adjectives.","translation":"在 calm and thoughtful response 这一短语中，calm 和 thoughtful 是并列形容词。","targetForm":"coordinate","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"To ensure a smooth launch, the design and engineering teams must coordinate their schedules.","translation":"为确保顺利发布，设计和工程团队必须协调各自的时间安排。","targetForm":"coordinate","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Although the agencies had different priorities, they coordinated relief deliveries after the storm.","translation":"尽管这些机构的优先事项不同，它们仍在暴风雨后协调了救援物资的运送。","targetForm":"coordinated","senseId":"source-v-1","sourceSenseId":"v-1"}]},"college":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"学会"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"学院"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"大学"}],"examples":[{"sentence":"Maybe the Electoral College isn’t such a peculiar idea, after all.","translation":"毕竟，选举人团理念或许并没有那么特殊。","targetForm":"college","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Because the college emphasizes interdisciplinary research, students are encouraged to collaborate across departments to solve complex problems.","translation":"由于该学院强调跨学科研究，鼓励学生跨部门合作以解决复杂问题。","targetForm":"college","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although college tuition has risen sharply, many students still pursue higher education because it significantly enhances career prospects.","translation":"尽管大学学费大幅上涨，许多学生仍然追求高等教育，因为它显着提升职业前景。","targetForm":"college","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"While some argue that college is not for everyone, statistics show that graduates earn substantially more over their lifetimes.","translation":"虽然有人认为大学并不适合所有人，但统计数据显示，毕业生一生中的收入要高得多。","targetForm":"college","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The college recently introduced a mentorship program, which pairs students with industry professionals to bridge the gap between theory and practice.","translation":"该学院最近推出了一个导师计划，将学生与行业专业人士配对，以弥合理论与实践之间的差距。","targetForm":"college","senseId":"source-n-1","sourceSenseId":"n-1"}]},"costly":{"senseGroups":[{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"费用大的"}],"examples":[{"sentence":"A poorly designed software system can lead to costly maintenance and frequent downtime, which ultimately affects user satisfaction.","translation":"一个设计不佳的软件系统可能导致昂贵的维护和频繁的停机，最终影响用户满意度。","targetForm":"costly","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"Although renewable energy infrastructure is costly to build, it reduces long-term operational expenses and environmental impact.","translation":"尽管可再生能源基础设施的建设成本高昂，但它减少了长期的运营费用和环境影响。","targetForm":"costly","senseId":"source-adj-3","sourceSenseId":"adj-3"}]},"could":{"senseGroups":[{"id":"source-aux-2","partOfSpeech":"aux.","sourceSenseIds":["aux-2"],"sense":"能"}],"examples":[{"sentence":"The good news is that there are three relatively simple interventions that could make a big difference.","translation":"好消息是有三种相对简单的干预方法能够带来巨大的不同。","targetForm":"could","senseId":"source-aux-2","sourceSenseId":"aux-2"}]},"compliment":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"称赞"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"恭维"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"敬意"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"称赞"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"褒扬"}],"examples":[{"sentence":"The professor received a sincere compliment from a colleague who admired the clarity of her latest research paper.","translation":"教授收到了一位同事真诚的称赞，这位同事很欣赏她最新研究论文的清晰性。","targetForm":"compliment","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"His remark was intended as a compliment, but she interpreted it as a subtle criticism of her work.","translation":"他的话本意是恭维，但她却将其理解为对自己工作的含蓄批评。","targetForm":"compliment","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The ambassador paid a high compliment to the host nation by praising its commitment to cultural preservation.","translation":"大使对东道国致力于文化保护表示赞扬，以此致以崇高的敬意。","targetForm":"compliment","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The manager complimented the team on their innovative approach, which had significantly improved the project's efficiency.","translation":"经理称赞了团队的创新方法，这显著提高了项目的效率。","targetForm":"complimented","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Critics complimented the director for her bold vision, which brought a fresh perspective to the classic play.","translation":"评论家褒扬了导演的大胆构想，这为这部经典戏剧带来了全新的视角。","targetForm":"complimented","senseId":"source-v-2","sourceSenseId":"v-2"}]},"consequently":{"senseGroups":[{"id":"source-adv-1","partOfSpeech":"adv.","sourceSenseIds":["adv-1"],"sense":"所以"}],"examples":[{"sentence":"The company failed to adapt to the digital market, and consequently it lost a significant share of its customer base to more agile competitors.","translation":"该公司未能适应数字市场，因此将大量客户份额输给了更灵活的竞争对手。","targetForm":"consequently","senseId":"source-adv-1","sourceSenseId":"adv-1"},{"sentence":"The heavy rainfall persisted for weeks, and consequently the river overflowed its banks, causing widespread flooding in the low-lying areas.","translation":"暴雨持续了数周，因此河水漫过堤岸，导致低洼地区大面积洪水泛滥。","targetForm":"consequently","senseId":"source-adv-1","sourceSenseId":"adv-1"},{"sentence":"The new regulations imposed stricter environmental standards, and consequently many factories had to invest in costly upgrades to remain compliant.","translation":"新法规实施了更严格的环境标准，因此许多工厂不得不投入巨资进行升级以保持合规。","targetForm":"consequently","senseId":"source-adv-1","sourceSenseId":"adv-1"},{"sentence":"The research team discovered a critical flaw in the methodology, and consequently the entire dataset had to be re-examined before publication.","translation":"研究团队发现方法中存在一个关键缺陷，因此整个数据集在发表前必须重新审查。","targetForm":"consequently","senseId":"source-adv-1","sourceSenseId":"adv-1"},{"sentence":"The government reduced funding for the arts, and consequently several renowned theater companies were forced to close their doors permanently.","translation":"政府削减了对艺术的资助，因此几家知名剧团被迫永久关闭。","targetForm":"consequently","senseId":"source-adv-1","sourceSenseId":"adv-1"}]},"condemn":{"senseGroups":[{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"谴责"}],"examples":[{"sentence":"Likewise, AU President Jean Ping condemned a coup in Guinea-Bissau in early April immediately and in the strongest terms.","translation":"类似地，今年4月初，非盟主席让·平（Jean Ping）用最强硬的口气批评了几内亚比绍的政变。","targetForm":"condemned","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"It is important to condemn racism, but that alone is not enough.","translation":"谴责种族主义很重要，但光是谴责种族主义是不够的。","targetForm":"condemn","senseId":"source-v-3","sourceSenseId":"v-3"}]},"couch":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"长沙发"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"躺下"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"表达"},{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"蹲伏"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"卧榻"}],"examples":[{"sentence":"The leather couch in the waiting room was so comfortable that several patients fell asleep while reading magazines.","translation":"候诊室里的皮沙发非常舒适，以至于几位病人在翻阅杂志时睡着了。","targetForm":"couch","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"After the long hike, she couched on the grassy bank and watched the clouds drift slowly across the sky.","translation":"长途徒步后，她在草坡上躺下，看着云朵缓缓飘过天空。","targetForm":"couched","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"The diplomat carefully couched his criticism in diplomatic language to avoid offending the host nation.","translation":"这位外交官谨慎地用外交辞令表达批评，以免冒犯东道国。","targetForm":"couched","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The cat couched in the tall grass, its muscles tense as it prepared to pounce on the unsuspecting bird.","translation":"猫蹲伏在高草丛中，肌肉紧绷，准备扑向那只毫无防备的鸟。","targetForm":"couched","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"A velvet couch from the Victorian era dominated the corner of the antique shop, its fabric still remarkably intact.","translation":"一张维多利亚时代的天鹅绒卧榻占据了古董店的一角，其面料依然完好无损。","targetForm":"couch","senseId":"source-n-3","sourceSenseId":"n-3"}]},"cop":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"警官"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"抓住"}],"examples":[{"sentence":"The cop who patrols the neighbourhood has earned trust through regular community engagement.","translation":"在这个社区巡逻的警官通过定期参与社区活动赢得了信任。","targetForm":"cop","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"A veteran cop can often de-escalate a tense situation without using force.","translation":"经验丰富的警官通常能够在不使用武力的情况下缓和紧张局面。","targetForm":"cop","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because the cop had training in crisis intervention, he guided the distressed resident toward support services.","translation":"由于这名警官受过危机干预训练，他引导情绪困扰的居民获得支持服务。","targetForm":"cop","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the cop faced public scrutiny, she followed procedure and recorded every decision carefully.","translation":"尽管这名警官受到公众监督，她仍遵循程序并仔细记录每一项决定。","targetForm":"cop","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"When the last bus left early, the students managed to cop a ride home with a neighbour.","translation":"末班车提前离开后，学生们设法搭邻居的车回了家。","targetForm":"cop","senseId":"source-v-1","sourceSenseId":"v-1"}]},"consist":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"组成"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"存在于"}],"examples":[{"sentence":"Japan consists of four major islands and over 3,000 small islands, and is about equal to California in area.","translation":"日本是由四个大岛和三千多个小岛组成的，面积和加州差不多。","targetForm":"consists","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Liberty consists of being able to make everything as harmless as possible.","translation":"自由旨在能够做所有不伤害其他人的事。","targetForm":"consists","senseId":"source-v-2","sourceSenseId":"v-2"}]},"continue":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"继续"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"延续"}],"examples":[{"sentence":"First, we will continue to support the institutions that helped get us to where we are now.","translation":"首先，我们将继续支持对实现当前目标做出贡献的机构。","targetForm":"continue","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Sixty years later, the Arab-Israeli conflict reminds us that the Jews’ journey back to history continues.","translation":"六十年之后，阿拉伯—以色列冲突提醒着我们犹太人重返历史的征程仍在继续。","targetForm":"continues","senseId":"source-v-2","sourceSenseId":"v-2"}]},"contaminate":{"senseGroups":[{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"污染"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"弄污"}],"examples":[{"sentence":"Industrial waste discharged into the river has contaminated the water supply, posing serious health risks to nearby communities.","translation":"排入河流的工业废物污染了供水，对附近社区构成了严重的健康风险。","targetForm":"contaminated","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"The laboratory took strict precautions to ensure that no external bacteria would contaminate the cell cultures during the experiment.","translation":"实验室采取了严格的预防措施，以确保在实验过程中没有外部细菌会污染细胞培养物。","targetForm":"contaminate","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"Improper handling of the ancient manuscript could contaminate its delicate pages with oils from human skin, accelerating deterioration.","translation":"不当处理这份古代手稿可能会使人皮肤上的油脂污染其脆弱的书页，从而加速其损坏。","targetForm":"contaminate","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The oil spill contaminated miles of pristine coastline, devastating marine ecosystems and local fisheries for years to come.","translation":"石油泄漏污染了数英里长的原始海岸线，对海洋生态系统和当地渔业造成了多年的毁灭性影响。","targetForm":"contaminated","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"Even trace amounts of heavy metals can contaminate soil, making it unsuitable for growing crops that are safe for human consumption.","translation":"即使是微量的重金属也会污染土壤，使其不适合种植可供人类安全食用的作物。","targetForm":"contaminate","senseId":"source-v-3","sourceSenseId":"v-3"}]},"companion":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"朋友"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"陪伴"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"指南"}],"examples":[{"sentence":"A loyal companion can reduce the stress of academic life, which otherwise may lead to burnout.","translation":"忠实的同伴可以减轻学业生活的压力，而这种压力本可能导致倦怠。","targetForm":"companion","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because a travel companion shares costs and experiences, the journey often becomes more affordable and memorable.","translation":"由于旅伴分担费用和经历，旅程往往更实惠也更难忘。","targetForm":"companion","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The older woman adopted a dog as a companion, thereby making her daily routine less isolated.","translation":"这位年长女士收养了一只狗作为伴侣，从而让日常生活不再那么孤单。","targetForm":"companion","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Although a study companion can increase motivation, compatible schedules are essential for regular work.","translation":"尽管学习伙伴能增强动力，相互契合的时间安排对持续学习至关重要。","targetForm":"companion","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The publisher issued a companion to the novel so that readers could explore its historical background.","translation":"出版社为这部小说出版了一本配套指南，使读者能了解其历史背景。","targetForm":"companion","senseId":"source-n-3","sourceSenseId":"n-3"}]},"compile":{"senseGroups":[{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"编纂"},{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"收集"}],"examples":[{"sentence":"If you compile a bibliography without proper citations, the academic integrity of your paper may be compromised.","translation":"如果你编纂参考文献时没有正确引用，你论文的学术诚信可能会受到损害。","targetForm":"compile","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"Although the data was scattered across multiple databases, the analyst managed to compile a unified report.","translation":"尽管数据分散在多个数据库中，分析师还是成功编纂了一份统一的报告。","targetForm":"compile","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"To ensure the anthology was comprehensive, the editor decided to compile works from both established and emerging authors.","translation":"为了确保选集全面，编辑决定收集知名作家和新锐作家的作品。","targetForm":"compile","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"Because the legal team needed accurate precedents, they spent weeks to compile relevant case law.","translation":"由于法律团队需要准确的先例，他们花了数周时间收集相关判例法。","targetForm":"compile","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"When researchers compile statistics from various sources, they must verify the reliability of each dataset.","translation":"当研究人员从各种来源汇编统计数据时，他们必须核实每个数据集的可靠性。","targetForm":"compile","senseId":"source-v-3","sourceSenseId":"v-3"}]},"code":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"代码"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"密码"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"法规"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"把...编码"},{"id":"source-other-1","partOfSpeech":"计算机","sourceSenseIds":["other-1"],"sense":"计算机代码","contextReviewed":true}],"examples":[{"sentence":"Developers write clear code so that their programs remain maintainable over time.","translation":"开发人员编写清晰的代码，使程序能长期保持可维护性。","targetForm":"code","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Before entering the archive, visitors must provide the access code issued by the library.","translation":"进入档案馆前，访客必须提供图书馆发放的访问密码。","targetForm":"code","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Because the building violated the fire code, authorities ordered renovations before it could reopen.","translation":"由于这栋建筑违反消防法规，当局下令翻修后才能重新开放。","targetForm":"code","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The research team will code each interview response so that patterns can be compared systematically.","translation":"研究团队将对每份访谈回答编码，以便系统地比较模式。","targetForm":"code","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Although the algorithm is efficient, its underlying code needs documentation for future maintenance.","translation":"尽管算法高效，它的底层程序代码仍需要文档说明，以便日后维护。","targetForm":"code","senseId":"source-other-1","sourceSenseId":"other-1"}]},"conquer":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"克服"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"征服"},{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"得胜"}],"examples":[{"sentence":"Although public speaking frightened her at first, steady practice helped her conquer that fear.","translation":"尽管公开演讲起初令她害怕，持续练习帮助她克服了这种恐惧。","targetForm":"conquer","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Because the team worked collaboratively, it conquered the complex project before the deadline.","translation":"由于团队协作工作，他们在截止日期前攻克了这项复杂任务。","targetForm":"conquered","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"If societies cannot conquer their reliance on fossil fuels, environmental damage will intensify.","translation":"如果社会无法克服对化石燃料的依赖，环境破坏将加剧。","targetForm":"conquer","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The history lesson examined how an empire sought to conquer neighbouring territories through military force.","translation":"历史课考察了一个帝国如何试图通过武力征服邻近领土。","targetForm":"conquer","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"When the underdog conquered the stronger side, the result surprised supporters across the league.","translation":"当弱队战胜更强的对手时，这一结果令整个联赛的支持者感到惊讶。","targetForm":"conquered","senseId":"source-v-4","sourceSenseId":"v-4"}]},"collide":{"senseGroups":[{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"抵触"}],"examples":[{"sentence":"In a rapidly changing society, traditional values often collide with modern lifestyles, creating tensions that require thoughtful resolution.","translation":"在快速变化的社会中，传统价值观常与现代生活方式发生冲突，产生需要深思熟虑才能解决的紧张关系。","targetForm":"collide","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"When the interests of economic growth and environmental protection collide, policymakers must carefully weigh long-term consequences.","translation":"当经济增长与环境保护的利益发生冲突时，决策者必须仔细权衡长期后果。","targetForm":"collide","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"If personal ambitions collide with team objectives, a leader must find a compromise that preserves both morale and productivity.","translation":"如果个人抱负与团队目标相抵触，领导者必须找到一个既能维护士气又能保持生产力的折中方案。","targetForm":"collide","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"The new regulation may collide with existing industry practices, so companies need to adjust their operations to ensure compliance.","translation":"新规定可能与现有行业惯例相冲突，因此企业需要调整运营以确保合规。","targetForm":"collide","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"The two research teams, working independently, discovered that their conclusions collide on a fundamental point, prompting a joint investigation.","translation":"两个独立工作的研究团队发现，他们的结论在一个基本点上相互矛盾，从而促使他们展开联合调查。","targetForm":"collide","senseId":"source-v-3","sourceSenseId":"v-3"}]},"conservation":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"保护"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"保存"}],"examples":[{"sentence":"Although conservation efforts have increased the panda population, habitat fragmentation remains a serious threat to their long-term survival.","translation":"尽管保护工作增加了大熊猫的数量，但栖息地破碎化仍对其长期生存构成严重威胁。","targetForm":"conservation","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The conservation of ancient manuscripts requires controlled temperature and humidity, which prevents further deterioration of the fragile paper.","translation":"古代手稿的保护需要控制温度和湿度，这可以防止脆弱纸张的进一步恶化。","targetForm":"conservation","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The conservation of marine biodiversity depends not only on reducing pollution but also on establishing sustainable fishing practices.","translation":"海洋生物多样性的保护不仅取决于减少污染，还取决于建立可持续的捕捞方式。","targetForm":"conservation","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because conservation of the wetlands is critical for migratory birds, the government has designated the area a protected reserve.","translation":"由于湿地保护对候鸟至关重要，政府已将该地区划为保护区。","targetForm":"conservation","senseId":"source-n-1","sourceSenseId":"n-1"}]},"cord":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"绳索"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"[医] 索","contextReviewed":true},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"带","contextReviewed":true}],"examples":[{"sentence":"The mountaineer used a durable nylon cord to secure the tent, which withstood the strong winds overnight.","translation":"登山者用一根耐用的尼龙绳固定帐篷，这使帐篷经受住了整夜的强风。","targetForm":"cord","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because the spinal cord is essential for transmitting neural signals, any injury can have severe consequences.","translation":"因为脊髓对于传递神经信号至关重要，任何损伤都可能带来严重后果。","targetForm":"cord","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The umbilical cord provides vital nutrients and oxygen to the fetus, while also removing waste products.","translation":"脐带为胎儿提供重要的营养物质和氧气，同时清除废物。","targetForm":"cord","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"In traditional bookbinding, artisans rely on a waxed cord to stitch the pages together, thereby creating a durable spine.","translation":"在传统书籍装订中，工匠依靠蜡线将书页缝合在一起，从而形成耐用的书脊。","targetForm":"cord","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The electrician replaced the worn extension cord to ensure the workshop met safety regulations.","translation":"电工更换了磨损的延长线，以确保车间符合安全规定。","targetForm":"cord","senseId":"source-n-1","sourceSenseId":"n-1"}]},"combine":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"(使)结合"}],"examples":[{"sentence":"My writing desk, a place of dread: an incredible number of incredibly useful drawers - combined with incredibly little legspace.","translation":"我的书桌很吓人：那么多那么有用抽屉，放在那么小、刚够伸腿的地方。","targetForm":"combined","senseId":"source-v-2","sourceSenseId":"v-2"}]},"contradict":{"senseGroups":[{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"与...矛盾"}],"examples":[{"sentence":"The latest results contradict a long-held assumption and require revision of the theoretical framework.","translation":"最新结果与长期假设相矛盾，并要求修订理论框架。","targetForm":"contradict","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"Although the witnesses' accounts seem to contradict each other, they may reflect different perspectives.","translation":"尽管两位证人的陈述似乎相互矛盾，它们可能反映了不同视角。","targetForm":"contradict","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"His public statements contradict his private actions, thereby weakening the trust placed in him.","translation":"他的公开声明与私下行为相矛盾，从而削弱了人们对他的信任。","targetForm":"contradict","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"When new data contradict established theories, scientists should reassess their hypotheses instead of dismissing evidence.","translation":"当新数据与既有理论矛盾时，科学家应重新评估假设，而非否定证据。","targetForm":"contradict","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"The investigation's findings contradict the initial report, which raises questions about the original inquiry.","translation":"调查结果与最初报告相矛盾，这引发了对原调查的质疑。","targetForm":"contradict","senseId":"source-v-3","sourceSenseId":"v-3"}]},"copper":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"铜"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"警察"}],"examples":[{"sentence":"Copper is widely used in electrical wiring because of its excellent conductivity and ductility.","translation":"铜因其优良的导电性和延展性而被广泛用于电线。","targetForm":"Copper","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The ancient civilization crafted intricate tools and ornaments from copper, which was abundant in the region.","translation":"这个古代文明用铜制作了复杂的工具和装饰品，因为该地区铜资源丰富。","targetForm":"copper","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The price of copper has surged recently due to increased demand from the renewable energy sector.","translation":"由于可再生能源行业需求增加，铜价最近大幅上涨。","targetForm":"copper","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The old copper kettle had developed a green patina over decades of use in the farmhouse kitchen.","translation":"这个旧铜壶在农舍厨房使用了数十年后，表面形成了一层绿色的铜绿。","targetForm":"copper","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The local copper, who had patrolled the neighborhood for twenty years, was known for his fairness and integrity.","translation":"那位在当地巡逻了二十年的警察以公正和正直著称。","targetForm":"copper","senseId":"source-n-2","sourceSenseId":"n-2"}]},"cocaine":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"可卡因"}],"examples":[{"sentence":"Because cocaine trafficking networks often exploit weak governance structures, international cooperation is vital to disrupt their operations.","translation":"由于可卡因贩运网络经常利用薄弱的治理结构，国际合作对于瓦解其运作至关重要。","targetForm":"cocaine","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although cocaine is sometimes glamorized in popular culture, its devastating effects on mental health and family stability are well-documented.","translation":"尽管可卡因有时在流行文化中被美化，但它对心理健康和家庭稳定的破坏性影响是有据可查的。","targetForm":"cocaine","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The chemical runoff from clandestine cocaine labs contaminates water sources, thereby endangering both aquatic life and the health of downstream communities.","translation":"秘密可卡因实验室的化学径流污染了水源，从而危及水生生物和下游社区的健康。","targetForm":"cocaine","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Lawmakers have proposed stricter penalties for cocaine possession, yet critics argue that such measures fail to address the root causes of addiction.","translation":"立法者提议对持有可卡因实施更严厉的处罚，但批评者认为这些措施未能解决成瘾的根本原因。","targetForm":"cocaine","senseId":"source-n-1","sourceSenseId":"n-1"}]},"commission":{"senseGroups":[{"id":"source-n-6","partOfSpeech":"n.","sourceSenseIds":["n-6"],"sense":"委托"}],"examples":[{"sentence":"But European support for the Afghan mission is in fact limited, and cooperation between the biggest EU donor governments and the European Commission remains inadequate.","translation":"但是事实上欧洲对阿富汗的支持却是非常有限的，而最大的欧盟捐助国与欧盟委员会之间的合作也相当不够。","targetForm":"commission","senseId":"source-n-6","sourceSenseId":"n-6"},{"sentence":"At the same time, Juncker does not buy soybeans – the European Commission has no such budget, and any such imports would ultimately be a private-sector decision.","translation":"与此同时，容克也没有买大豆 — — 欧盟没有这一预算，一切大豆进口交易说到底都是私人部门的决定。","targetForm":"commission","senseId":"source-n-6","sourceSenseId":"n-6"}]},"coherent":{"senseGroups":[{"id":"source-adj-5","partOfSpeech":"adj.","sourceSenseIds":["adj-5"],"sense":"连贯的"}],"examples":[{"sentence":"A coherent argument needs logical reasoning as well as reliable evidence to support every major claim.","translation":"连贯的论证既需要逻辑推理，也需要可靠证据来支持每项主要主张。","targetForm":"coherent","senseId":"source-adj-5","sourceSenseId":"adj-5"},{"sentence":"Although the essay had interesting ideas, it lacked a coherent structure that readers could easily follow.","translation":"尽管文章有不少有趣观点，它缺乏读者容易理解的连贯结构。","targetForm":"coherent","senseId":"source-adj-5","sourceSenseId":"adj-5"},{"sentence":"The team developed a coherent framework that combines economic, social, and environmental factors in assessing sustainability.","translation":"团队构建了连贯框架，将经济、社会和环境因素结合起来评估可持续性。","targetForm":"coherent","senseId":"source-adj-5","sourceSenseId":"adj-5"},{"sentence":"Because the policy proposal was not coherent, it failed to gain support from legislators or the public.","translation":"由于政策提案不连贯，它未能获得立法者或公众的支持。","targetForm":"coherent","senseId":"source-adj-5","sourceSenseId":"adj-5"},{"sentence":"Effective communication presents information in a coherent order so that an audience can grasp the main points.","translation":"有效沟通以连贯顺序呈现信息，使受众能够把握要点。","targetForm":"coherent","senseId":"source-adj-5","sourceSenseId":"adj-5"}]},"courtyard":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"庭院"}],"examples":[{"sentence":"The courtyard, which was paved with weathered flagstones, offered a quiet retreat from the bustling city streets.","translation":"铺着风化石板的庭院为人们提供了一个远离喧嚣城市街道的安静休憩之所。","targetForm":"courtyard","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the building's facade appeared austere, its inner courtyard revealed an unexpected lushness of climbing roses and jasmine.","translation":"尽管建筑的外立面显得朴素，其内部庭院却展现出攀援玫瑰和茉莉意想不到的繁茂。","targetForm":"courtyard","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because the courtyard garden was designed with drought-resistant plants, it required minimal irrigation even during the dry season.","translation":"由于庭院花园采用了耐旱植物设计，即使在旱季也只需很少的灌溉。","targetForm":"courtyard","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The courtyard served as a communal space where residents gathered for celebrations, thereby strengthening the social fabric of the neighborhood.","translation":"庭院作为一个公共空间，居民们在此聚集庆祝，从而增强了邻里的社会凝聚力。","targetForm":"courtyard","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Scholars have noted that the traditional courtyard house, by integrating open and enclosed areas, creates a microclimate that moderates temperature extremes.","translation":"学者们注意到，传统庭院住宅通过融合开放与封闭区域，创造出一种调节极端温度的微气候。","targetForm":"courtyard","senseId":"source-n-1","sourceSenseId":"n-1"}]},"cough":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"咳嗽"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"咳嗽"}],"examples":[{"sentence":"A persistent cough lasting more than three weeks should be evaluated by a qualified healthcare professional.","translation":"持续超过三周的咳嗽应由合格的医疗专业人员进行评估。","targetForm":"cough","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because air pollution irritates the respiratory tract, residents in industrial cities may develop a chronic cough.","translation":"由于空气污染刺激呼吸道，工业城市居民可能出现慢性咳嗽。","targetForm":"cough","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The patient's dry cough became worse at night, so the doctor arranged further assessment.","translation":"患者的干咳在夜间加重，因此医生安排了进一步评估。","targetForm":"cough","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although cough suppressants may bring temporary relief, treating the cause is important for recovery.","translation":"尽管止咳药可能带来暂时缓解，处理病因对康复仍很重要。","targetForm":"cough","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Public-health campaigns advise people to cough into an elbow rather than a hand to reduce the spread of germs.","translation":"公共卫生宣传建议人们咳嗽时对着手肘而不是手，以减少病菌传播。","targetForm":"cough","senseId":"source-v-1","sourceSenseId":"v-1"}]},"cow":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"母牛"}],"examples":[{"sentence":"When the cow flies high and the ox flies low, there probably is a twister.","translation":"当母牛飞得高, 公牛飞得低, 就有可能是一个龙卷风。","targetForm":"cow","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"I don't like being the one who always has to milk the cow.","translation":"我不喜欢做那个总是挤牛奶的人。","targetForm":"cow","senseId":"source-n-1","sourceSenseId":"n-1"}]},"cook":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"厨师"}],"examples":[{"sentence":"Lucy might be able to help you, if you can't cook dinner for ten people alone.","translation":"露西也许能帮你的忙，如果你一人做不来十个人的晚饭。","targetForm":"cook","senseId":"source-n-2","sourceSenseId":"n-2"}]},"correlate":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"相关物"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"相关"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"使有相互关系"}],"examples":[{"sentence":"The study identified a strong correlate between regular exercise and improved cardiovascular health.","translation":"该研究发现定期锻炼与改善心血管健康之间存在强相关因素。","targetForm":"correlate","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Researchers often examine socioeconomic status as a correlate of academic achievement.","translation":"研究人员经常将社会经济地位视为学业成就的一个相关因素。","targetForm":"correlate","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The data clearly correlates increased screen time with a decline in sleep quality among adolescents.","translation":"数据清楚地表明，青少年屏幕时间的增加与睡眠质量下降相关。","targetForm":"correlates","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Economists have correlated the rise in inflation with the expansion of the money supply.","translation":"经济学家已将通货膨胀的上升与货币供应量的扩张联系起来。","targetForm":"correlated","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The scientist is correlating the experimental results with the theoretical predictions to validate the model.","translation":"科学家正在将实验结果与理论预测相关联，以验证该模型。","targetForm":"correlating","senseId":"source-v-1","sourceSenseId":"v-1"}]},"conscience":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"良心"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"道德感","contextReviewed":true},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"正义感","contextReviewed":true}],"examples":[{"sentence":"Because his conscience would not allow him to profit from the error, he returned the overpayment without being asked.","translation":"因为良心不允许他从这个错误中获利，他没有等人要求便退回了多付的钱。","targetForm":"conscience","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the proposal was legal, it troubled her conscience because it shifted the cost onto vulnerable families.","translation":"尽管这项提议合法，它仍令她良心不安，因为它把成本转嫁给了弱势家庭。","targetForm":"conscience","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The documentary appealed to the public conscience by showing how easily neglected communities can be ignored.","translation":"这部纪录片通过展现被忽视的社区多么容易遭到漠视，唤起了公众的道德感。","targetForm":"conscience","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"She regarded refusing the bribe as a matter of conscience rather than a calculation of professional risk.","translation":"她把拒收贿赂视为良心问题，而非对职业风险的算计。","targetForm":"conscience","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"A resilient democracy depends on citizens whose conscience remains alert to injustice, even when speaking out is inconvenient.","translation":"有韧性的民主制度有赖于公民保持对不公的正义感，即使发声会带来不便。","targetForm":"conscience","senseId":"source-n-4","sourceSenseId":"n-4"}]},"connection":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"关系"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"连接"}],"examples":[{"sentence":"That parrot was Tobias's only connection with his late father.","translation":"那只鹦鹉是托比亚斯与他已故父亲之间唯一的连结。","targetForm":"connection","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"At first I thought the development board was up the spout, but it was just a loose connection.","translation":"本来以为是开发板给我弄坏了，原来是电源线接触不良。","targetForm":"connection","senseId":"source-n-1","sourceSenseId":"n-1"}]},"contend":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"斗争"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"竞争"},{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"为...斗争"}],"examples":[{"sentence":"Several researchers contend that public libraries remain essential because they provide free access to reliable information.","translation":"多位研究者主张，公共图书馆仍然不可或缺，因为它们让人们能够免费获得可靠信息。","targetForm":"contend","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Small firms must contend with rising costs while protecting the quality that earned customers' trust.","translation":"小企业必须应对不断上涨的成本，同时守住赢得顾客信任的品质。","targetForm":"contend","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The finalists will contend for the scholarship after presenting proposals to an independent panel.","translation":"决赛选手将在向独立评审团陈述方案后，竞争这项奖学金。","targetForm":"contend","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"Local groups contended for safer crossings when the original road plan ignored nearby schools.","translation":"原道路方案忽视附近学校时，当地团体为更安全的过街设施而争取。","targetForm":"contended","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"Although commentators contend that remote work weakens teamwork, the evidence is far from conclusive.","translation":"尽管评论者认为远程办公会削弱团队合作，但现有证据远未形成定论。","targetForm":"contend","senseId":"source-v-2","sourceSenseId":"v-2"}]},"combat":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"争斗"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"战斗"}],"examples":[{"sentence":"The government launched a new initiative to combat air pollution, which has reached hazardous levels in urban areas.","translation":"政府发起了一项新举措来对抗空气污染，因为城市地区的污染已达到危险水平。","targetForm":"combat","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"While hand-to-hand combat is rare in modern warfare, it is still taught to enhance soldiers' confidence and agility.","translation":"尽管徒手格斗在现代战争中很少见，但仍被教授以增强士兵的信心和敏捷性。","targetForm":"combat","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Although modern combat relies heavily on technology, the psychological resilience of soldiers remains crucial.","translation":"尽管现代战斗严重依赖技术，但士兵的心理韧性仍然至关重要。","targetForm":"combat","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Because combat experience can lead to post-traumatic stress, veterans require comprehensive mental health support.","translation":"由于战斗经历可能导致创伤后应激障碍，退伍军人需要全面的心理健康支持。","targetForm":"combat","senseId":"source-n-2","sourceSenseId":"n-2"}]},"convenient":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"方便的"},{"id":"source-adj-4","partOfSpeech":"adj.","sourceSenseIds":["adj-4"],"sense":"适当而可行的","contextReviewed":true}],"examples":[{"sentence":"The online booking system is convenient because it lets patients change appointments without making a phone call.","translation":"这个在线预约系统很方便，因为病人无需打电话便能更改预约。","targetForm":"convenient","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Although the office is small, its location beside the station is convenient for visiting clients.","translation":"尽管办公室不大，它紧邻车站的位置对来访客户很方便。","targetForm":"convenient","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"It may be convenient to blame one department, but the evidence shows that several systems failed together.","translation":"把责任归咎于一个部门或许省事，但证据表明多个系统同时出了问题。","targetForm":"convenient","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Please choose a convenient time when the entire project team can discuss the revised budget.","translation":"请选一个方便的时间，让整个项目团队都能讨论修订后的预算。","targetForm":"convenient","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"A short pilot is a convenient and proportionate way to test the policy before a national launch.","translation":"在全国推广前进行短期试点，是检验这项政策的一种合宜且适当的方式。","targetForm":"convenient","senseId":"source-adj-4","sourceSenseId":"adj-4"}]},"consultant":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"顾问"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"[医] 顾问医师","contextReviewed":true}],"examples":[{"sentence":"The management consultant recommended a comprehensive restructuring plan to improve operational efficiency.","translation":"管理顾问建议了一项全面的重组计划，以提高运营效率。","targetForm":"consultant","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"A financial consultant was hired to analyze the company's investment portfolio and suggest diversification strategies.","translation":"聘请了一位财务顾问来分析公司的投资组合并提出多元化策略。","targetForm":"consultant","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"As a legal consultant, she provides expert advice on intellectual property rights to technology startups.","translation":"作为一名法律顾问，她为科技初创公司提供知识产权方面的专业建议。","targetForm":"consultant","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The consultant physician reviewed the patient's medical history before recommending a new treatment protocol.","translation":"顾问医师在推荐新的治疗方案之前，审查了患者的病史。","targetForm":"consultant","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"After the initial diagnosis, the general practitioner referred the case to a consultant for further evaluation.","translation":"初步诊断后，全科医生将病例转交给顾问医师进行进一步评估。","targetForm":"consultant","senseId":"source-n-3","sourceSenseId":"n-3"}]},"cottage":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"小屋"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"茅舍"}],"examples":[{"sentence":"The old cottage had only one bed, so we all took turns sleeping in it.","translation":"那间旧屋里只有一张床，所以我们便轮流睡觉。","targetForm":"cottage","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"He lives alone in a little cottage in the swamp.","translation":"他独自一人住在沼泽地里的一栋小屋里。","targetForm":"cottage","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"There was a cottage on the side of the hill.","translation":"山坡上有一个茅屋。","targetForm":"cottage","senseId":"source-n-2","sourceSenseId":"n-2"}]},"coupon":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"赠券"},{"id":"source-n-5","partOfSpeech":"n.","sourceSenseIds":["n-5"],"sense":"联票","contextReviewed":true},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"息票"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"利息单","contextReviewed":true}],"examples":[{"sentence":"She clipped a coupon from the magazine to receive a discount on her next grocery purchase.","translation":"她从杂志上剪下一张赠券，以便在下次购买杂货时获得折扣。","targetForm":"coupon","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The travel agency offered a coupon book that included vouchers for local attractions and restaurants.","translation":"旅行社提供了一本联票册，其中包括当地景点和餐厅的优惠券。","targetForm":"coupon","senseId":"source-n-5","sourceSenseId":"n-5"},{"sentence":"Investors receive interest payments when the bond's coupon is detached and presented to the issuer.","translation":"当债券的息票被撕下并提交给发行方时，投资者会收到利息支付。","targetForm":"coupon","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The bond's coupon rate determines the periodic interest income that the holder will earn.","translation":"债券的息票利率决定了持有人将获得的定期利息收入。","targetForm":"coupon","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"He carefully filed the interest coupons to ensure accurate tax reporting at the end of the fiscal year.","translation":"他仔细地将利息单归档，以确保在财政年度结束时准确报税。","targetForm":"coupons","senseId":"source-n-4","sourceSenseId":"n-4"}]},"council":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"会议"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"委员会"}],"examples":[{"sentence":"Finally, Council meetings should be open when legislative matters are at stake, so that citizens can know who voted for what and according to which criteria.","translation":"最后，当立法无法奏效的时候，就应该召开欧盟理事会会议，这样公民们就能知道谁该根据哪种标准为什么投票。","targetForm":"council","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The crisis of compliance starts at the top of the UN system and trickles down, through the Security Council, to the General Assembly and member governments.","translation":"守法危机始于联合国体系顶层并向下扩散，通过安理会直至联大及各成员国政府。","targetForm":"council","senseId":"source-n-2","sourceSenseId":"n-2"}]},"component":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"元件"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"组件"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"成分"},{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"组成的"}],"examples":[{"sentence":"Before the aircraft entered service, engineers tested every component repeatedly under extreme temperature and pressure.","translation":"飞机投入使用前，工程师在极端温度和压力下反复测试每个元件。","targetForm":"component","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The security component of the application was updated separately so that the rest of the system could remain online.","translation":"该应用的安全组件被单独更新，以便系统其余部分能够保持在线。","targetForm":"component","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Trust is an essential component of effective teamwork because people share difficult information only when they feel safe.","translation":"信任是高效团队合作的基本组成部分，因为人们只有感到安全时才会分享困难的信息。","targetForm":"component","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The report compares the component parts of each proposal before considering how they would work together in practice.","translation":"报告先比较每项提议的组成部分，再考察它们在实践中如何协同运作。","targetForm":"component","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Although cost is a significant component of the decision, environmental impact must also be considered carefully.","translation":"尽管成本是决策中的重要组成部分，环境影响也必须得到仔细考量。","targetForm":"component","senseId":"source-n-3","sourceSenseId":"n-3"}]},"cousin":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"表兄弟姊妹"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"堂（表）兄弟姐妹；表亲","contextReviewed":true}],"examples":[{"sentence":"My cousin offered to review my application because she had recently completed the same programme.","translation":"我的表姐愿意帮我审阅申请材料，因为她最近刚完成同一个项目。","targetForm":"cousin","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Although the cousins grew up in different cities, they kept in touch through weekly video calls.","translation":"尽管这些表亲在不同城市长大，他们仍通过每周视频通话保持联系。","targetForm":"cousins","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"When her cousin arrived from abroad, the family planned a quiet dinner instead of a large celebration.","translation":"当她的表亲从国外到达时，全家安排了一顿安静的晚餐，而没有举办大型庆祝活动。","targetForm":"cousin","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"A distant cousin shared photographs that helped the family reconstruct the history of an old house.","translation":"一位远房表亲分享了照片，帮助这家人还原一栋老房子的历史。","targetForm":"cousin","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Because my cousin speaks the local dialect, she made our first visit to the village much easier.","translation":"由于我的表亲会说当地的方言，她让我们第一次去村子的行程顺利许多。","targetForm":"cousin","senseId":"source-n-3","sourceSenseId":"n-3"}]},"constrain":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"强迫"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"限制"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"关押"}],"examples":[{"sentence":"The court order constrained the corporation to disclose all internal communications related to the case.","translation":"法院命令强迫该公司披露所有与案件相关的内部通信。","targetForm":"constrained","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Strict budget cuts constrained the research team from exploring more innovative experimental approaches.","translation":"严格的预算削减限制了研究团队探索更具创新性的实验方法。","targetForm":"constrained","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The narrow scope of the regulation constrains the agency’s ability to address emerging environmental threats.","translation":"该法规的狭窄范围限制了该机构应对新出现的环境威胁的能力。","targetForm":"constrains","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The suspect was constrained in a holding cell while awaiting further questioning by the detectives.","translation":"嫌疑人在等待侦探进一步审问时被关押在拘留室中。","targetForm":"constrained","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"Feeling constrained by the rigid corporate culture, she eventually resigned to start her own venture.","translation":"由于感到受到僵化企业文化的限制，她最终辞职创办了自己的企业。","targetForm":"constrained","senseId":"source-v-2","sourceSenseId":"v-2"}]},"cosmic":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"宇宙的"},{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"无限的"},{"id":"source-adj-4","partOfSpeech":"adj.","sourceSenseIds":["adj-4"],"sense":"有秩序的"}],"examples":[{"sentence":"The cosmic microwave background radiation provides crucial evidence for the Big Bang theory.","translation":"宇宙微波背景辐射为大爆炸理论提供了关键证据。","targetForm":"cosmic","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Scientists study cosmic rays to understand high-energy processes occurring in distant galaxies.","translation":"科学家研究宇宙射线以了解发生在遥远星系中的高能过程。","targetForm":"cosmic","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The cosmic perspective gained from space exploration has profoundly influenced philosophical thought.","translation":"从太空探索中获得的宇宙视角深刻影响了哲学思想。","targetForm":"cosmic","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The cosmic scale of the universe makes human endeavors seem insignificant by comparison.","translation":"宇宙的宏大尺度使得人类的努力相比之下显得微不足道。","targetForm":"cosmic","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"Ancient philosophers believed in a cosmic order that governed both the heavens and human affairs.","translation":"古代哲学家相信一种宇宙秩序，它支配着天体和人类事务。","targetForm":"cosmic","senseId":"source-adj-4","sourceSenseId":"adj-4"}]},"counsel":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"忠告"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"法律顾问"}],"examples":[{"sentence":"Although she was confident in her decision, she still valued the wise counsel of her retired professor.","translation":"尽管她对自己的决定充满信心，但她仍然重视退休教授的明智忠告。","targetForm":"counsel","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The defendant's counsel presented a compelling argument, which ultimately swayed the jury in favor of acquittal.","translation":"被告的律师提出了令人信服的论点，最终使陪审团倾向于无罪释放。","targetForm":"counsel","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Because the contract contained ambiguous clauses, the startup sought legal counsel to avoid future disputes.","translation":"由于合同包含模糊条款，这家初创公司寻求法律顾问以避免未来纠纷。","targetForm":"counsel","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The CEO ignored the counsel of the risk management team, a decision that later resulted in significant financial loss.","translation":"首席执行官忽视了风险管理团队的忠告，这一决定后来导致了重大财务损失。","targetForm":"counsel","senseId":"source-n-2","sourceSenseId":"n-2"}]},"compact":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"紧凑的"},{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"简洁的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"紧密的"}],"examples":[{"sentence":"Although the apartment is compact, its intelligent layout creates a sense of spaciousness that larger homes often lack.","translation":"尽管这套公寓很紧凑，但其智能布局营造出宽敞感，这是许多大户型所缺乏的。","targetForm":"compact","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The compact car not only consumes less fuel but also reduces emissions, which makes it an environmentally friendly choice.","translation":"紧凑型汽车不仅油耗更低，而且减少排放，这使其成为环保的选择。","targetForm":"compact","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Because the new smartphone has a compact design, it fits comfortably in small pockets while still offering a large screen.","translation":"由于这款新智能手机设计紧凑，它能舒适地放入小口袋，同时仍提供大屏幕。","targetForm":"compact","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The researcher presented a compact summary of the findings, which allowed the audience to grasp the key points within minutes.","translation":"研究人员对研究结果进行了简洁的总结，使听众在几分钟内就掌握了要点。","targetForm":"compact","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"When you compact the soil before planting, you ensure that the roots have a stable base, thereby promoting healthier growth.","translation":"在种植前压实土壤，可以确保根系有稳定的基础，从而促进更健康的生长。","targetForm":"compact","senseId":"source-adj-2","sourceSenseId":"adj-2"}]},"counterpart":{"senseGroups":[{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"相应物"}],"examples":[{"sentence":"While the northern region suffered from severe drought, its southern counterpart experienced record rainfall and devastating floods.","translation":"北方地区遭受严重干旱，而南方地区却遭遇了创纪录的降雨和毁灭性的洪水。","targetForm":"counterpart","senseId":"source-n-4","sourceSenseId":"n-4"}]},"communicate":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"传达"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"感染"},{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"通讯"}],"examples":[{"sentence":"The report communicates the central finding clearly, while its charts allow readers to examine the supporting evidence.","translation":"报告清楚传达了核心发现，图表则让读者能够查看支持性证据。","targetForm":"communicates","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Scientists must communicate uncertainty honestly so that the public understands both the strength and the limits of the evidence.","translation":"科学家必须诚实传达不确定性，使公众理解证据的力量和局限。","targetForm":"communicate","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Health workers explained how the infection can be communicated through close contact when basic precautions are ignored.","translation":"卫生人员解释了在忽视基本防护时，感染如何通过密切接触传播。","targetForm":"communicated","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"Although the manager was abroad, she communicated with the team by video link each morning.","translation":"尽管经理在国外，她仍每天早晨通过视频连线与团队沟通。","targetForm":"communicated","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"The exhibition communicates a sense of loss through empty rooms rather than through lengthy explanations.","translation":"这场展览通过空荡的房间而非冗长说明传达了一种失落感。","targetForm":"communicates","senseId":"source-v-2","sourceSenseId":"v-2"}]},"convention":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"大会"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"协定"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"惯例"},{"id":"source-other-1","partOfSpeech":"计算机","sourceSenseIds":["other-1"],"sense":"约定","contextReviewed":true}],"examples":[{"sentence":"The convention brought teachers together to exchange practical methods for supporting multilingual learners.","translation":"这次大会让教师们聚在一起，交流支持多语学习者的实用方法。","targetForm":"convention","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the convention was ambitious, countries agreed to report their progress at regular intervals.","translation":"尽管这项公约雄心勃勃，各国仍同意定期报告进展。","targetForm":"convention","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"By convention, the chair invites quieter members to speak before the group reaches a decision.","translation":"按照惯例，主席会在小组作出决定前邀请较沉默的成员发言。","targetForm":"convention","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"When writers follow the convention for citations, readers can trace the evidence behind each claim.","translation":"当作者遵循引文惯例时，读者就能追溯每个论点背后的证据。","targetForm":"convention","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The team documented its naming convention so that future developers could understand the codebase quickly.","translation":"团队记录了命名约定，让未来的开发者能够迅速理解代码库。","targetForm":"convention","senseId":"source-other-1","sourceSenseId":"other-1"}]},"cock":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"龙头"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"公鸡"}],"examples":[{"sentence":"Because the old water cock was leaking, the plumber installed a new one to prevent water waste.","translation":"因为旧水龙头漏水，水管工安装了一个新的以防止浪费水。","targetForm":"cock","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The farmer relied on the cock, which served as a natural alarm clock for the entire household.","translation":"农夫依赖那只公鸡，它充当了全家人的天然闹钟。","targetForm":"cock","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"When the cock strutted across the barnyard, the hens followed him in a neat line.","translation":"当公鸡在谷仓空地上大摇大摆地走过时，母鸡们排成整齐的一行跟着他。","targetForm":"cock","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the cock crowed at dawn, the villagers had already begun their daily chores.","translation":"尽管公鸡在黎明时啼叫，村民们早已开始了日常劳作。","targetForm":"cock","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The engineer adjusted the safety cock carefully, thereby ensuring that the pressure remained stable.","translation":"工程师仔细调整了安全旋塞，从而确保压力保持稳定。","targetForm":"cock","senseId":"source-n-3","sourceSenseId":"n-3"}]},"complex":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"综合体"}],"examples":[{"sentence":"At the same time, complex models can be useful for illustrating special cases and reminding us that the world is a messy place.","translation":"与此同时，复杂模型在说明特殊情况、提醒我们世界是一个混乱场所方面很有用。","targetForm":"complex","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"That leaves three larger countries where the issues are more complex: Japan (about 125 million people), Malaysia (around 30 million people), and Vietnam (90 million people).","translation":"其他三个较大国家的问题比较复杂：日本（人口1.25亿左右 ） 、 马来西亚 （人口3,000万 ） 、 和越南（人口9,000万 ） 。","targetForm":"complex","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"That said, in such a complex environment, investors can be expected to reach widely disparate conclusions, which will sustain – if not increase – market volatility.","translation":"尽管如此，在如此复杂的环境中，投资者可能形成大相径庭的结论，而这将维持 — — 乃至加剧 — — 市场的波动。","targetForm":"complex","senseId":"source-n-1","sourceSenseId":"n-1"}]},"cognitive":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"认知的"}],"examples":[{"sentence":"While cognitive psychology focuses on internal mental processes, behavioral psychology examines observable actions and their environmental triggers.","translation":"认知心理学关注内部心理过程，而行为心理学则研究可观察的行为及其环境触发因素。","targetForm":"cognitive","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Although cognitive biases can distort our judgment, we can mitigate their effects through deliberate reflection and evidence-based reasoning.","translation":"尽管认知偏差可能扭曲我们的判断，但我们可以通过深思熟虑和基于证据的推理来减轻其影响。","targetForm":"cognitive","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Because cognitive development in early childhood lays the foundation for future learning, educators emphasize play-based activities that stimulate curiosity.","translation":"由于儿童早期的认知发展为未来的学习奠定基础，教育工作者强调能够激发好奇心的游戏活动。","targetForm":"cognitive","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"To ensure accurate diagnosis, clinicians must assess cognitive impairment using standardized tests rather than relying solely on subjective reports.","translation":"为了确保准确诊断，临床医生必须使用标准化测试评估认知障碍，而不是仅仅依赖主观报告。","targetForm":"cognitive","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The study revealed that regular aerobic exercise improves cognitive function, which is particularly beneficial for older adults at risk of dementia.","translation":"研究表明，定期进行有氧运动可以改善认知功能，这对有痴呆风险的老年人尤其有益。","targetForm":"cognitive","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"contrive":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"设计"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"发明"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"图谋"}],"examples":[{"sentence":"The engineer contrived a mechanism that converts waste heat into electricity with remarkable efficiency.","translation":"这位工程师设计了一种机制，能以卓越的效率将废热转化为电能。","targetForm":"contrived","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"She contrived a clever solution to the scheduling conflict that satisfied all parties involved.","translation":"她设计了一个巧妙的解决方案，解决了日程冲突，让所有相关方都满意。","targetForm":"contrived","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The team is contriving a new composite material that could revolutionize the aerospace industry.","translation":"该团队正在发明一种新型复合材料，可能会彻底改变航空航天工业。","targetForm":"contriving","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Despite limited resources, they contrived a way to purify water using only sunlight and basic filters.","translation":"尽管资源有限，他们还是发明了一种仅用阳光和基本过滤器净化水的方法。","targetForm":"contrived","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The prisoners contrived an escape plan that involved digging a tunnel over several months.","translation":"囚犯们图谋了一个越狱计划，包括用几个月时间挖掘一条隧道。","targetForm":"contrived","senseId":"source-v-3","sourceSenseId":"v-3"}]},"conscious":{"senseGroups":[{"id":"source-adj-5","partOfSpeech":"adj.","sourceSenseIds":["adj-5"],"sense":"清醒的","contextReviewed":true},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"知觉的"},{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"觉察的"},{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"有意识的"}],"examples":[{"sentence":"The patient remained fully conscious throughout the complex surgical procedure, which lasted several hours.","translation":"在持续数小时的复杂外科手术过程中，病人始终保持完全清醒。","targetForm":"conscious","senseId":"source-adj-5","sourceSenseId":"adj-5"},{"sentence":"She was barely conscious after the accident, yet she managed to provide her contact details to the paramedics.","translation":"事故发生后她几乎失去知觉，但仍设法向急救人员提供了自己的联系方式。","targetForm":"conscious","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"The researchers observed that the subjects became conscious of subtle changes in their environment after the training program.","translation":"研究人员观察到，受试者在培训项目结束后开始觉察到环境中细微的变化。","targetForm":"conscious","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"A conscious effort to reduce carbon emissions is essential if we are to mitigate the effects of climate change.","translation":"若要减轻气候变化的影响，有意识地努力减少碳排放至关重要。","targetForm":"conscious","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The company is highly conscious of its social responsibilities and has implemented several green initiatives.","translation":"该公司高度意识到自身的社会责任，并已实施多项环保举措。","targetForm":"conscious","senseId":"source-adj-3","sourceSenseId":"adj-3"}]},"consume":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"消耗"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"消费"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"消灭"}],"examples":[{"sentence":"Because data centres consume vast amounts of electricity, many operators are investing in renewable energy contracts.","translation":"由于数据中心消耗大量电力，许多运营商正在投资可再生能源合同。","targetForm":"consume","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The new process consumes less water than the older system, which reduces the factory's environmental impact.","translation":"新流程比旧系统消耗更少的水，从而减少了工厂的环境影响。","targetForm":"consumes","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"When people consume information from unreliable sources, they may form opinions based on incomplete evidence.","translation":"当人们摄取不可靠来源的信息时，可能基于不完整证据形成看法。","targetForm":"consume","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Although the wildfire consumed large areas of forest, firefighters protected the nearby homes through the night.","translation":"尽管野火吞噬了大片森林，消防员仍彻夜保护了附近房屋。","targetForm":"consumed","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"The complex legal dispute consumed so much time that the committee postponed all less urgent decisions.","translation":"这场复杂的法律争议耗费了大量时间，以至于委员会推迟了所有不那么紧急的决定。","targetForm":"consumed","senseId":"source-v-1","sourceSenseId":"v-1"}]},"considerate":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"体贴的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"体谅的"},{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"考虑周到的"}],"examples":[{"sentence":"A considerate colleague shares the agenda early so that everyone has time to prepare.","translation":"一位体贴的同事会提前分享议程，让每个人都有时间准备。","targetForm":"considerate","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Although the building was old, designers made it more considerate of visitors with limited mobility.","translation":"尽管建筑很旧，设计师仍让它更能体谅行动不便的访客。","targetForm":"considerate","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"Because the tutor was considerate, she offered another appointment when the student became ill.","translation":"由于导师很体谅人，学生生病时她提供了另一个预约时间。","targetForm":"considerate","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"When planning an event, it is considerate to provide clear information about access and timing.","translation":"策划活动时，清楚说明通行方式和时间安排是考虑周到的做法。","targetForm":"considerate","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"The manager's considerate response prevented a small scheduling problem from becoming a serious conflict.","translation":"经理体贴周到的回应避免了一个小小的排班问题演变成严重冲突。","targetForm":"considerate","senseId":"source-adj-3","sourceSenseId":"adj-3"}]},"concession":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"让步"}],"examples":[{"sentence":"As a concession to local residents, the construction company limited working hours, thereby reducing noise pollution in the neighborhood.","translation":"作为对当地居民的让步，建筑公司限制了工作时间，从而减少了社区的噪音污染。","targetForm":"concession","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Although the government made a significant concession by reducing carbon emissions, environmental groups argued that the measures were still insufficient.","translation":"尽管政府通过减少碳排放做出了重大让步，环保组织仍认为这些措施不够充分。","targetForm":"concession","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Because a well-timed concession can build trust during negotiations, diplomats often use it as a strategic tool to reach agreements.","translation":"因为适时的让步能在谈判中建立信任，外交官们常将其作为达成协议的战略工具。","targetForm":"concession","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The company offered a concession on overtime pay, which helped to avert a prolonged strike that would have disrupted production.","translation":"公司提供了加班费方面的让步，这有助于避免一场会扰乱生产的长期罢工。","targetForm":"concession","senseId":"source-n-2","sourceSenseId":"n-2"}]},"confess":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"承认"},{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"供认"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"坦白"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"忏悔"}],"examples":[{"sentence":"The researcher had to confess that the data did not support the original hypothesis, so the study was revised.","translation":"研究人员不得不承认数据不支持最初假设，因此修订了研究。","targetForm":"confess","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Although the defendant first denied the charge, he later confessed after consulting an independent lawyer.","translation":"尽管被告起初否认指控，他在咨询独立律师后仍作出了供认。","targetForm":"confessed","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"She confessed to forgetting the appointment rather than inventing an excuse that would damage trust further.","translation":"她坦白自己忘记了预约，而没有编造会进一步损害信任的借口。","targetForm":"confessed","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"In the memoir, the minister confessed that the policy had produced consequences nobody had anticipated.","translation":"在回忆录中，这位部长承认该政策产生了无人预料的后果。","targetForm":"confessed","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Before the ceremony, he chose to confess his wrongdoing privately and ask for forgiveness from those affected.","translation":"仪式前，他选择私下忏悔自己的过错，并向受影响的人请求原谅。","targetForm":"confess","senseId":"source-v-3","sourceSenseId":"v-3"}]},"compensate":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"补偿"}],"examples":[{"sentence":"The new policy aims to compensate employees for overtime through additional leave days rather than monetary payments.","translation":"新政策旨在通过额外的休假日而非货币支付来补偿员工的加班。","targetForm":"compensate","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Because the drought severely damaged crops, the government implemented a program to compensate farmers for their financial losses.","translation":"因为干旱严重损害了庄稼，政府实施了一项计划来补偿农民的经济损失。","targetForm":"compensate","senseId":"source-v-2","sourceSenseId":"v-2"}]},"coincidence":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"巧合"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"同时发生"}],"examples":[{"sentence":"It was a remarkable coincidence that both researchers submitted papers on the same obscure topic within hours of each other.","translation":"两位研究人员在几小时内就同一冷门课题提交了论文，这真是一个惊人的巧合。","targetForm":"coincidence","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The coincidence of their birthdays, which fell on the same day, led to a joint celebration every year.","translation":"他们的生日恰好在同一天，这种巧合使得每年都会举办联合庆祝活动。","targetForm":"coincidence","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"By sheer coincidence, the two old friends met at a remote café in a foreign city where neither expected to see anyone familiar.","translation":"纯粹出于巧合，这两位老朋友在异国城市一个偏僻的咖啡馆相遇，两人都没想到会见到熟人。","targetForm":"coincidence","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The coincidence of the lunar eclipse with the winter solstice was an event that astronomers had long anticipated.","translation":"月食与冬至同时发生是天文学家们期待已久的事件。","targetForm":"coincidence","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The coincidence of rising unemployment and falling consumer confidence posed a serious challenge for policymakers.","translation":"失业率上升与消费者信心下降同时发生，给政策制定者带来了严峻挑战。","targetForm":"coincidence","senseId":"source-n-2","sourceSenseId":"n-2"}]},"concert":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"音乐会"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"一致"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"协力"}],"examples":[{"sentence":"Although the concert began late, the performers gave the audience a memorable final piece.","translation":"尽管音乐会开始得晚，表演者仍为观众献上了一首难忘的终曲。","targetForm":"concert","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The choir sang in concert, and its careful harmony made the familiar song sound new.","translation":"合唱团协同演唱，精心的和声让熟悉的歌曲听起来焕然一新。","targetForm":"concert","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"When the departments concert their efforts, they can solve complex problems without duplicating work.","translation":"当各部门协调努力时，他们能解决复杂问题而不重复劳动。","targetForm":"concert","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Because the concert supported local charities, volunteers helped visitors find their seats efficiently.","translation":"由于音乐会支持当地慈善机构，志愿者帮助观众高效找到座位。","targetForm":"concert","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The schools worked in concert to share specialist teachers between smaller classes.","translation":"这些学校协力合作，在较小班级之间共享专业教师。","targetForm":"concert","senseId":"source-v-1","sourceSenseId":"v-1"}]},"colonial":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"殖民的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"殖民地的"}],"examples":[{"sentence":"Because colonial powers often suppressed local industries, newly independent countries faced significant challenges when building self-sufficient economies.","translation":"由于殖民列强经常压制当地工业，新独立的国家在建立自给自足的经济时面临重大挑战。","targetForm":"colonial","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The colonial administration implemented policies that prioritized resource extraction, thereby hindering long-term sustainable development in the region.","translation":"殖民政府实施了优先资源开采的政策，从而阻碍了该地区的长期可持续发展。","targetForm":"colonial","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"Although the colonial era ended decades ago, its economic legacy continues to shape trade patterns in many developing nations.","translation":"尽管殖民时代几十年前就结束了，但其经济遗产仍在影响许多发展中国家的贸易模式。","targetForm":"colonial","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"If historians fail to examine colonial narratives critically, they risk perpetuating biased perspectives that obscure the experiences of indigenous peoples.","translation":"如果历史学家未能批判性地审视殖民叙事，他们就有可能延续掩盖原住民经历的偏见观点。","targetForm":"colonial","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"While colonial architecture attracts tourists, it also serves as a reminder of a painful history that many communities prefer not to revisit.","translation":"虽然殖民建筑吸引游客，但它也提醒着许多社区不愿重温的痛苦历史。","targetForm":"colonial","senseId":"source-adj-2","sourceSenseId":"adj-2"}]},"commemorate":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"纪念"}],"examples":[{"sentence":"The statue of the Minute Man commemorates the valiant soldiers who fought in the Revolutionary War.","translation":"民兵雕像是为了纪念独立战争中英勇作战的士兵。","targetForm":"commemorates","senseId":"source-v-1","sourceSenseId":"v-1"}]},"contemplate":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"沉思"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"盘算"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"注视"}],"examples":[{"sentence":"She sat beside the river to contemplate the changes that had taken place in the town.","translation":"她坐在河边，沉思小镇已经发生的变化。","targetForm":"contemplate","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The board is contemplating a smaller trial before committing public money to the full programme.","translation":"董事会正在考虑先进行较小规模试点，再投入公共资金实施完整项目。","targetForm":"contemplating","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"Visitors paused to contemplate the painting before reading the historical note beside it.","translation":"访客停下来凝视画作，然后阅读旁边的历史说明。","targetForm":"contemplate","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"He contemplated moving closer to work after several winters of difficult commuting.","translation":"经历几个冬季艰难通勤后，他考虑搬到离工作地点更近的地方。","targetForm":"contemplated","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"The article invites readers to contemplate how ordinary choices can affect a shared environment.","translation":"文章邀请读者思考普通选择如何影响共同环境。","targetForm":"contemplate","senseId":"source-v-2","sourceSenseId":"v-2"}]},"consolidate":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"巩固"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"使联合"},{"id":"source-other-1","partOfSpeech":"计算机","sourceSenseIds":["other-1"],"sense":"合并计算","contextReviewed":true},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"统一"}],"examples":[{"sentence":"Although the team had made progress, it needed to consolidate its learning before starting a harder topic.","translation":"尽管团队已经取得进展，开始更难主题前仍需要巩固所学内容。","targetForm":"consolidate","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The council consolidated several small services so that residents could find support in one place.","translation":"市政委员会合并了几项小型服务，让居民能在一个地方获得支持。","targetForm":"consolidated","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"When the system consolidates records from different offices, staff can identify duplicate requests more easily.","translation":"当系统合并不同办事处的记录时，员工能更容易发现重复请求。","targetForm":"consolidates","senseId":"source-other-1","sourceSenseId":"other-1"},{"sentence":"Because the university consolidated its archives, researchers no longer needed to visit several separate buildings.","translation":"由于大学整合了档案，研究人员不再需要前往几栋不同的建筑。","targetForm":"consolidated","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"The school held revision workshops to consolidate key ideas before the final assessments began.","translation":"学校在期末评估开始前举办了复习研讨会来巩固关键概念。","targetForm":"consolidate","senseId":"source-v-1","sourceSenseId":"v-1"}]},"conservative":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"保守的"}],"examples":[{"sentence":"Finally, Trump will nominate conservative justices for the Supreme Court, which has had one vacancy since Justice Antonin Scalia died in February.","translation":"最后，特朗普将提名保守派法官进入最高法院，2月份安东宁·斯卡利亚（Antonin Scalia）法官逝世后，最高法院已经出现了一个空缺。","targetForm":"conservative","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The sense of inevitability could be dispelled by recent shifts in the internal politics of both the Conservative government and the Labour opposition.","translation":"不可避免感可能因为最近在保守党政府和工党反对派内部政治局面的改变而消失。","targetForm":"conservative","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Because the engineer used a conservative safety factor, the bridge withstood forces far beyond the expected load.","translation":"由于工程师使用了保守的安全系数，这座桥承受了远超预期负荷的力量。","targetForm":"conservative","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"comfortable":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"舒服的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"轻松的"}],"examples":[{"sentence":"Although the cabin was modest, its quiet lighting and generous windows made the long journey surprisingly comfortable.","translation":"尽管船舱朴素，柔和的灯光和宽大的窗户仍让漫长旅程出人意料地舒适。","targetForm":"comfortable","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"A comfortable chair cannot compensate for poor posture, yet thoughtful design can reduce fatigue during sustained work.","translation":"舒适的椅子不能弥补不良坐姿，但周到的设计能减轻长时间工作带来的疲劳。","targetForm":"comfortable","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"She became comfortable challenging the proposal only after the chair made clear that dissent would be taken seriously.","translation":"主席明确表示会认真对待异议后，她才自在地对这项提议提出质疑。","targetForm":"comfortable","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"The hotel provided a comfortable base from which researchers could reach remote villages before sunrise.","translation":"这家酒店为研究人员提供了舒适的落脚点，使他们能在日出前抵达偏远村庄。","targetForm":"comfortable","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Rather than becoming comfortable with ambiguous data, the team postponed publication until the missing records were verified.","translation":"团队没有安于含糊的数据，而是推迟发表，直到核实缺失记录。","targetForm":"comfortable","senseId":"source-adj-2","sourceSenseId":"adj-2"}]},"concern":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"忧虑"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"关心"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"与...有关"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"使担心"}],"examples":[{"sentence":"Public concern grew after residents learned that the old factory site might contain contaminated soil.","translation":"居民得知旧工厂用地可能含有受污染土壤后，公众担忧加剧。","targetForm":"concern","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The committee's main concern was whether the new timetable would disadvantage students who commute long distances.","translation":"委员会最关切的是，新时间表是否会让长途通勤的学生处于不利地位。","targetForm":"concern","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"This question concerns the quality of the evidence, not the personal views of the researchers.","translation":"这个问题涉及证据质量，而非研究人员的个人观点。","targetForm":"concerns","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The delay concerned parents because the school had not explained when normal classes would resume.","translation":"学校没有说明正常课程何时恢复，因此延误使家长担忧。","targetForm":"concerned","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Environmental concerns should be considered before a new road is built through the wetland.","translation":"在湿地中修建新道路前，应考虑环境方面的关切。","targetForm":"concerns","senseId":"source-n-1","sourceSenseId":"n-1"}]},"conclusion":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"结论"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"结尾"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"缔结；签订","contextReviewed":true}],"examples":[{"sentence":"The committee reached the conclusion that postponing the vote would allow affected residents to be heard properly.","translation":"委员会得出结论，推迟表决能让受影响居民得到充分陈述的机会。","targetForm":"conclusion","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"It is tempting to jump to a conclusion from a striking anecdote, but a single story rarely establishes a general rule.","translation":"人们容易从一个醒目的轶事仓促下结论，但单一故事很少能证明普遍规律。","targetForm":"conclusion","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"In the conclusion of the report, which follows a comparative analysis, the authors distinguish short-term savings from lasting social value.","translation":"在报告结尾，作者在比较分析之后区分了短期节约与持久的社会价值。","targetForm":"conclusion","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The evidence supports the conclusion that early feedback improves revision, provided students are given time to act on it.","translation":"证据支持这样的结论：只要给学生落实反馈的时间，早期反馈就能改善修改效果。","targetForm":"conclusion","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The conclusion of the treaty, which required months of negotiation, depended on rules for sharing the river's water fairly.","translation":"该条约的缔结历经数月谈判，取决于能否就公平分配河水制定规则。","targetForm":"conclusion","senseId":"source-n-4","sourceSenseId":"n-4"}]},"consent":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"同意"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"同意"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"许可"}],"examples":[{"sentence":"The archive released the letters only with the writer's consent, because several passages concerned living relatives.","translation":"档案馆只在作者同意后才公开这些信件，因为其中几段涉及仍在世的亲属。","targetForm":"consent","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Participants gave informed consent after the researchers explained how recordings would be stored, used, and eventually deleted.","translation":"研究人员说明录音将如何保存、使用和最终删除后，参与者作出了知情同意。","targetForm":"consent","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although she disagreed with several details, she consented to the revised timetable so that the project could proceed.","translation":"尽管她不同意若干细节，仍同意修改后的时间表，以便项目得以推进。","targetForm":"consented","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"No photograph may be reproduced without consent from the rights holder, whose permission must be recorded in writing.","translation":"未经权利人同意，任何照片不得复制，其许可必须以书面形式记录。","targetForm":"consent","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The board consented to an independent review after community groups raised concerns about the proposed redevelopment.","translation":"社区团体对拟议改造提出担忧后，董事会同意进行独立审查。","targetForm":"consented","senseId":"source-v-1","sourceSenseId":"v-1"}]},"comfort":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"舒适"}],"examples":[{"sentence":"He worked hard in order that his family might live in comfort.","translation":"他努力工作为了让他的家人可以过舒适的生活。","targetForm":"comfort","senseId":"source-n-1","sourceSenseId":"n-1"}]},"consensus":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"一致"},{"id":"source-other-1","partOfSpeech":"计算机","sourceSenseIds":["other-1"],"sense":"计算机合意","contextReviewed":true}],"examples":[{"sentence":"Although the committee began with different views, it reached a consensus after comparing the evidence.","translation":"尽管委员会起初观点不同，比较证据后仍达成了共识。","targetForm":"consensus","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The scientific consensus changed only after several independent studies produced similar results.","translation":"只有在多项独立研究得出相似结果后，科学共识才发生改变。","targetForm":"consensus","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"When a consensus emerges through open discussion, people are more willing to support the final plan.","translation":"当共识通过开放讨论形成时，人们更愿意支持最终计划。","targetForm":"consensus","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Because the system uses consensus rules, every approved change must be confirmed by several participants.","translation":"由于系统使用共识规则，每项批准的变更都必须由多位参与者确认。","targetForm":"consensus","senseId":"source-other-1","sourceSenseId":"other-1"},{"sentence":"The absence of consensus delayed the decision, although everyone agreed that action was necessary.","translation":"缺乏共识延迟了决定，尽管所有人都同意必须采取行动。","targetForm":"consensus","senseId":"source-n-2","sourceSenseId":"n-2"}]},"conductor":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"领导者"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"售票员"},{"id":"source-n-5","partOfSpeech":"n.","sourceSenseIds":["n-5"],"sense":"[化] 导体","contextReviewed":true},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"指挥者"}],"examples":[{"sentence":"As a conductor of social change, the organization bridges gaps between communities, rather than imposing top-down solutions.","translation":"作为社会变革的引导者，该组织在社区之间架起桥梁，而不是强加自上而下的解决方案。","targetForm":"conductor","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The train conductor announced the delay, which was caused by unexpected track maintenance, to keep passengers informed.","translation":"列车长宣布了由意外轨道维护造成的延误，以便让乘客了解情况。","targetForm":"conductor","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Because copper is an excellent conductor of electricity, it is widely used in power transmission lines.","translation":"因为铜是优良的电导体，它被广泛用于输电线路。","targetForm":"conductor","senseId":"source-n-5","sourceSenseId":"n-5"},{"sentence":"The bus conductor patiently assisted passengers with their luggage, which ensured a smooth boarding process.","translation":"公交车售票员耐心地帮助乘客搬运行李，这确保了顺畅的上车过程。","targetForm":"conductor","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The orchestra's conductor used precise gestures to unify the musicians, thereby creating a harmonious performance.","translation":"乐团的指挥用精准的手势统一了乐手，从而创造了一场和谐的演出。","targetForm":"conductor","senseId":"source-n-2","sourceSenseId":"n-2"}]},"conceal":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"隐藏"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"掩盖"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"隐瞒"}],"examples":[{"sentence":"Dense fog concealed the mountain path, so the guide postponed the climb until the weather improved.","translation":"浓雾遮住了山路，因此向导把登山推迟到天气好转之后。","targetForm":"concealed","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The redesigned cabinet conceals the cables while leaving technicians enough room to inspect the equipment.","translation":"重新设计的柜体把电缆隐藏起来，同时给技术人员留下足够空间检查设备。","targetForm":"conceals","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"A transparent budget should reveal the assumptions rather than conceal the costs behind vague categories.","translation":"透明的预算应当披露假设，而不是把成本掩盖在含糊的类别之后。","targetForm":"conceal","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"She tried to conceal her surprise, although the sudden pause in her reply made it obvious.","translation":"她试图掩饰惊讶，尽管回答时突然停顿已经暴露了这一点。","targetForm":"conceal","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The agreement prohibited either side from concealing information that could affect the final safety assessment.","translation":"协议禁止任何一方隐瞒可能影响最终安全评估的信息。","targetForm":"concealing","senseId":"source-v-3","sourceSenseId":"v-3"}]},"congratulation":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"祝贺"}],"examples":[{"sentence":"She received messages of congratulations after her article was accepted by the student journal.","translation":"她的文章被学生期刊接受后，收到了许多祝贺信息。","targetForm":"congratulations","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"A simple note of congratulation can mean a great deal to someone completing a difficult task.","translation":"对完成艰巨任务的人而言，一张简单的祝贺便条也很有意义。","targetForm":"congratulation","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The award ceremony ended with congratulations for every team that had contributed to the project.","translation":"颁奖仪式以祝贺每个为项目作出贡献的团队结束。","targetForm":"congratulations","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"His letter offered warm congratulations but also encouraged the group to continue improving its methods.","translation":"他的信表达了热烈祝贺，同时鼓励团队继续改进方法。","targetForm":"congratulations","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The director sent a personal message of congratulation to the trainee who had solved the technical problem.","translation":"主任向解决技术问题的实习生发去了个人祝贺信息。","targetForm":"congratulation","senseId":"source-n-1","sourceSenseId":"n-1"}]},"concise":{"senseGroups":[{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"简明的"},{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"简洁的"}],"examples":[{"sentence":"A concise introduction can establish the topic without repeating background information that readers already know.","translation":"简明的引言能够交代主题，而不重复读者已经知道的背景信息。","targetForm":"concise","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"Although her reply was concise, it addressed every practical concern raised by the review panel.","translation":"尽管她的答复很简洁，它回应了评审小组提出的每一项实际问题。","targetForm":"concise","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The guide uses concise headings so that visitors can locate essential safety information within seconds.","translation":"这份指南使用简洁的标题，以便访客能在几秒内找到关键安全信息。","targetForm":"concise","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Rather than adding another paragraph, the editor suggested a concise sentence that linked the evidence to the claim.","translation":"编辑没有再加一段，而是建议用一句简洁的话把证据与论点连接起来。","targetForm":"concise","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The most concise version of the proposal retained the data table but removed decorative language and repetition.","translation":"提案最简洁的版本保留了数据表，但删除了修饰性语言和重复内容。","targetForm":"concise","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"comment":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"评论"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"批评"}],"examples":[{"sentence":"Because the politician's comment was taken out of context, it sparked unnecessary controversy among the public.","translation":"由于这位政治家的评论被断章取义，它在公众中引发了不必要的争议。","targetForm":"comment","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The professor's comment on my essay, which pointed out several logical fallacies, helped me improve my argumentation skills.","translation":"教授对我论文的评论指出了几个逻辑谬误，帮助我提高了论证能力。","targetForm":"comment","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Although the manager's comment was brief, it provided clear guidance on the project's next steps.","translation":"尽管经理的评论很简短，但它为项目的下一步提供了明确的指导。","targetForm":"comment","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Her insightful comment during the meeting, which drew on recent data, convinced the team to adopt a new strategy.","translation":"她在会议上的深刻评论引用了最新数据，说服团队采用了新策略。","targetForm":"comment","senseId":"source-n-3","sourceSenseId":"n-3"}]},"countryside":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"乡下地方"}],"examples":[{"sentence":"The bus route connects the countryside with the nearest hospital, market, and secondary school.","translation":"这条公交线路把农村地区与最近的医院、市场和中学连接起来。","targetForm":"countryside","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Many visitors come to the countryside in autumn to walk through forests and see the changing leaves.","translation":"许多游客秋天来到乡下，穿过森林散步并欣赏变色的树叶。","targetForm":"countryside","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The programme supports countryside communities that have lost shops, banks, and regular public transport.","translation":"该项目支持失去商店、银行和定期公共交通的农村社区。","targetForm":"countryside","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"She moved to the countryside because she wanted more time for gardening and quieter evenings.","translation":"她搬到乡下，因为希望有更多时间园艺并享受更安静的夜晚。","targetForm":"countryside","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The survey asked whether young people could find suitable work in the countryside after graduation.","translation":"调查询问年轻人毕业后能否在农村地区找到合适工作。","targetForm":"countryside","senseId":"source-n-1","sourceSenseId":"n-1"}]},"coalition":{"senseGroups":[{"id":"source-n-5","partOfSpeech":"n.","sourceSenseIds":["n-5"],"sense":"联盟","contextReviewed":true}],"examples":[{"sentence":"On the other hand, a center-right coalition between the Christian Democrats and the Free Democrats could spark the ECB into action.","translation":"另一方面，基督教民主党和自由民主党的中右翼联盟也可能会刺激欧洲央行采取行动。","targetForm":"coalition","senseId":"source-n-5","sourceSenseId":"n-5"}]},"corrode":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"使腐蚀"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"侵蚀"},{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"被侵蚀"}],"examples":[{"sentence":"Although stainless steel is resistant to many chemicals, prolonged exposure to chloride ions can still corrode its surface.","translation":"尽管不锈钢耐多种化学物质，但长期暴露于氯离子仍会腐蚀其表面。","targetForm":"corrode","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"If we fail to address the underlying issues, resentment will slowly corrode the team's morale, despite superficial harmony.","translation":"如果我们未能解决根本问题，尽管表面和谐，怨恨会慢慢侵蚀团队的士气。","targetForm":"corrode","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The constant friction from the moving parts can corrode the protective coating, which eventually leads to mechanical failure.","translation":"运动部件的持续摩擦会腐蚀保护涂层，最终导致机械故障。","targetForm":"corrode","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"When industrial emissions combine with moisture in the atmosphere, they form acids that corrode marble statues and buildings.","translation":"当工业排放物与大气中的水分结合时，会形成酸，腐蚀大理石雕像和建筑。","targetForm":"corrode","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Because the ancient coins were buried in acidic soil for centuries, the metal began to corrode, obscuring the inscriptions.","translation":"由于这些古钱币在酸性土壤中埋藏了几个世纪，金属开始腐蚀，使铭文变得模糊。","targetForm":"corrode","senseId":"source-v-4","sourceSenseId":"v-4"}]},"collapse":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"倒塌"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"瓦解"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"崩溃"},{"id":"source-v-5","partOfSpeech":"v.","sourceSenseIds":["v-5"],"sense":"折叠"},{"id":"source-other-1","partOfSpeech":"计算机","sourceSenseIds":["other-1"],"sense":"计算机中折叠内容","contextReviewed":true}],"examples":[{"sentence":"The collapse of the roof followed years of neglected repairs, which inspectors had repeatedly identified in earlier reports.","translation":"屋顶倒塌源于多年来被忽视的维修问题，检查人员曾在早期报告中反复指出。","targetForm":"collapse","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Without a clear succession plan, the partnership could collapse when its founding members eventually retire.","translation":"若没有明确的继任计划，这一合作关系可能在创始成员最终退休时瓦解。","targetForm":"collapse","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"Although the market did not collapse overnight, confidence weakened gradually as promised reforms failed to appear.","translation":"尽管市场没有一夜崩溃，随着承诺的改革迟迟未出现，信心逐渐削弱。","targetForm":"collapse","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The stage crew collapsed the temporary backdrop after the rehearsal, so that the hall could be used for another event.","translation":"彩排结束后，舞台工作人员拆叠临时背景板，以便礼堂用于另一场活动。","targetForm":"collapsed","senseId":"source-v-5","sourceSenseId":"v-5"},{"sentence":"To make the report easier to scan, the editor allowed readers to collapse detailed notes beneath each main section.","translation":"为使报告更易浏览，编辑允许读者折叠每个主要部分下方的详细注释。","targetForm":"collapse","senseId":"source-other-1","sourceSenseId":"other-1"}]},"coward":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"胆小的人"}],"examples":[{"sentence":"John is brave in appearance, but is in reality a coward.","translation":"约翰看起来很勇敢，但其实是个胆小鬼。","targetForm":"coward","senseId":"source-n-2","sourceSenseId":"n-2"}]},"concrete":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"混凝土"},{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"具体的"},{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"混凝土的"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"用混凝土浇筑"}],"examples":[{"sentence":"The engineers inspected the concrete after winter storms had exposed several cracks near the drainage channel.","translation":"冬季暴风雨暴露出排水渠附近几处裂缝后，工程师检查了混凝土。","targetForm":"concrete","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The report needs concrete examples to show how the proposed changes would affect people in daily life.","translation":"报告需要具体例子，以说明拟议变化会如何影响人们的日常生活。","targetForm":"concrete","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Although the goal sounds ambitious, the team has a concrete timetable and a clear method for measuring progress.","translation":"尽管目标听起来雄心勃勃，团队已有具体时间表和衡量进展的明确方法。","targetForm":"concrete","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The concrete steps outside the station were repaired with a textured finish to reduce slipping in rain.","translation":"车站外的混凝土台阶用有纹理的表面修复，以减少雨天打滑。","targetForm":"concrete","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"Workers concreted the narrow path only after drainage pipes had been installed beneath the surface.","translation":"工人在地面下安装排水管后，才用混凝土铺设狭窄小路。","targetForm":"concreted","senseId":"source-v-2","sourceSenseId":"v-2"}]},"confer":{"senseGroups":[{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"协商"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"带来"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"授予"}],"examples":[{"sentence":"The committee will confer with external experts before making a final decision, thereby ensuring a well-informed outcome.","translation":"委员会将在做出最终决定之前与外部专家协商，从而确保结果充分知情。","targetForm":"confer","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"Because the new policy could confer significant advantages on small businesses, it has received widespread support.","translation":"由于新政策可能给小企业带来显着优势，它得到了广泛支持。","targetForm":"confer","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"When leaders confer with stakeholders, they can identify potential risks that might otherwise be overlooked.","translation":"当领导者与利益相关者协商时，他们能够识别出可能被忽视的潜在风险。","targetForm":"confer","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"Universities confer degrees upon students who have fulfilled all academic requirements, which serves as a formal recognition of their achievement.","translation":"大学授予满足所有学术要求的学生学位，这是对他们成就的正式认可。","targetForm":"confer","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Although the award may confer prestige, it does not guarantee long-term career success.","translation":"尽管这个奖项可能带来声望，但它并不能保证长期的职业成功。","targetForm":"confer","senseId":"source-v-2","sourceSenseId":"v-2"}]},"contest":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"竞赛"}],"examples":[{"sentence":"The contest, which was judged by a panel of industry experts, emphasized practical impact over theoretical elegance.","translation":"由行业专家小组评审的比赛强调实际影响而非理论上的优雅。","targetForm":"contest","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"By entering the contest, participants not only gained recognition but also received mentorship from established professionals.","translation":"通过参加比赛，参与者不仅获得了认可，还得到了资深专业人士的指导。","targetForm":"contest","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The contest rules stipulated that all submissions must be original, thereby ensuring a fair evaluation process.","translation":"比赛规则规定所有提交作品必须为原创，从而确保了公平的评审过程。","targetForm":"contest","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the contest was open to amateurs, the winning entry demonstrated professional-level expertise.","translation":"尽管比赛对业余爱好者开放，但获奖作品展示了专业水平的专业知识。","targetForm":"contest","senseId":"source-n-1","sourceSenseId":"n-1"}]},"contain":{"senseGroups":[{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"控制"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"包含"}],"examples":[{"sentence":"The question now is whether Western institutions are strong enough to contain the global plutocracy that low interest rates have wrought.","translation":"现在的问题是西方制度是否足够强大，能够遏制低利率所造就的全球财阀。","targetForm":"contain","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"This, the official doctrine of most developed countries today, contains at least five major fallacies, which pass largely unnoticed, because the narrative is so plausible.","translation":"这便是如今大多数发达国家的指导方针，但其中至少有五大漏洞，而由于财政整合说听起来无懈可击，因此这五大漏洞很少有人注意到。","targetForm":"contains","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"In theory, governments in such a situation have five basic options to contain crisis conditions, pending the effects of measures to reinvigorate growth and employment engines.","translation":"理论上，面临这一情况的政府有五个基本选择遏制危机，等待重振增长和就业引擎的措施起效。","targetForm":"contain","senseId":"source-v-3","sourceSenseId":"v-3"}]},"confidence":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"信心"}],"examples":[{"sentence":"The only way world confidence can return dramatically is if our thinking coordinates around some inspiring story beyond that of the price increases themselves.","translation":"世界各国对经济的信心快速恢复的唯一途径是，我们的想法围绕着除了价格上涨这个故事本身之外的某个鼓舞人心的故事，协调一致。","targetForm":"confidence","senseId":"source-n-1","sourceSenseId":"n-1"}]},"comprehend":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"理解"}],"examples":[{"sentence":"Grave as these setbacks may be, the scale of Germany’s difficulties can be comprehended only once their causal link with developments in Italy is grasped.","translation":"尽管后果极其严重，但只有理解了德国与意大利发展之间的因果关系，才能深入了解德国目前所面临的困境。","targetForm":"comprehended","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Many people are unable to comprehend the actions of hackers.","translation":"很多人无法理解黑客们的行为。","targetForm":"comprehend","senseId":"source-v-1","sourceSenseId":"v-1"}]},"context":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"背景"}],"examples":[{"sentence":"France’s seemingly natural propensity to intervene is reinforced in this case by three key factors: Sarkozy, Qaddafi, and the context of a wider Arab revolution.","translation":"此次有三种关键因素巩固了法国似乎与生俱来的干涉倾向： 萨科奇、卡扎菲和阿拉伯革命大环境。","targetForm":"context","senseId":"source-n-2","sourceSenseId":"n-2"}]},"corporation":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"公司"}],"examples":[{"sentence":"Corporations and the military depend on assessment and sorting devices that are little more than disguised intelligence tests.","translation":"也许必须对智力给予一些关注，然而忽略起码是同样重要的认知能力—这一趋势却不合理：正是这种能力支撑起理性的思维和行为。","targetForm":"corporations","senseId":"source-n-1","sourceSenseId":"n-1"}]},"control":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"控制"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"克制"},{"id":"source-n-5","partOfSpeech":"n.","sourceSenseIds":["n-5"],"sense":"操纵装置"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"控制"},{"id":"source-other-1","partOfSpeech":"计算机","sourceSenseIds":["other-1"],"sense":"计算机中的控制或控制器","contextReviewed":true}],"examples":[{"sentence":"The laboratory introduced quality control at every stage, so that a single faulty measurement would not distort the final result.","translation":"实验室在每个阶段引入质量控制，使单个错误测量不会扭曲最终结果。","targetForm":"control","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although she was frustrated, she kept control of her response and asked for the evidence before making an accusation.","translation":"尽管她感到沮丧，仍控制住自己的反应，并在指责前要求查看证据。","targetForm":"control","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The operator adjusted the control slowly because a sudden movement could put pressure on the ageing machinery.","translation":"操作员缓慢调整控制装置，因为突然移动可能给老旧机械施加压力。","targetForm":"control","senseId":"source-n-5","sourceSenseId":"n-5"},{"sentence":"The team controlled access to the archive, which protected sensitive records while allowing approved researchers to work.","translation":"团队控制档案访问权限，既保护敏感记录，也让获批研究者能够工作。","targetForm":"controlled","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The application uses a control panel that lets administrators change permissions without editing the underlying code.","translation":"该应用使用控制面板，使管理员无需编辑底层代码即可更改权限。","targetForm":"control","senseId":"source-other-1","sourceSenseId":"other-1"}]},"contribute":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"有助于"}],"examples":[{"sentence":"ADDIS ABABA – Climate change will hit Africa – a continent that has contributed virtually nothing to bring it about – first and hardest.","translation":"亚的斯亚贝巴 — — 气候变化最先、也最沉重地打击了非洲这块从未造成过气候变化的大陆。","targetForm":"contributed","senseId":"source-v-1","sourceSenseId":"v-1"}]},"coincide":{"senseGroups":[{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"重合","contextReviewed":true},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"一致"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"符合"}],"examples":[{"sentence":"The launch will coincide with the annual festival, so organisers arranged quieter times for local residents to use the square.","translation":"发布活动将与年度节日同时举行，因此组织者安排了更安静的时段供当地居民使用广场。","targetForm":"coincide","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"The results of the two surveys coincided closely, which gave the researchers more confidence in the overall pattern.","translation":"两项调查结果高度一致，使研究人员对整体规律更有信心。","targetForm":"coincided","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"When economic incentives coincide with environmental goals, practical changes are easier for businesses to maintain over time.","translation":"当经济激励与环境目标一致时，企业更容易长期保持实际改变。","targetForm":"coincide","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"On the map, the proposed boundary did not coincide with the river, despite earlier documents suggesting that it would.","translation":"在地图上，拟议边界没有与河流重合，尽管早期文件曾表明会重合。","targetForm":"coincide","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"The deadline happened to coincide with the school holiday, which made it harder for parents to attend the consultation.","translation":"截止日期恰好与学校假期重合，使家长更难参加咨询。","targetForm":"coincide","senseId":"source-v-3","sourceSenseId":"v-3"}]},"controversy":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"论争"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"争论"}],"examples":[{"sentence":"The controversy over the redevelopment did not end with the vote, because residents disagreed about how the benefits would be shared.","translation":"围绕改造项目的争议没有随着表决结束，因为居民对利益如何分配仍有分歧。","targetForm":"controversy","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the controversy attracted attention, the authors asked readers to examine the original evidence before taking a position.","translation":"尽管争议引人关注，作者仍请读者在表态前审查原始证据。","targetForm":"controversy","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"A scientific controversy can be productive when competing explanations lead researchers to design better tests.","translation":"当相互竞争的解释促使研究人员设计更好的检验时，科学争议可以具有建设性。","targetForm":"controversy","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The museum addressed the controversy directly by explaining which objects had uncertain origins and how they were being investigated.","translation":"博物馆直接回应争议，说明哪些物品来源不确定，以及如何对其进行调查。","targetForm":"controversy","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Rather than prolonging the controversy with personal accusations, the chair returned the discussion to the documented facts.","translation":"主席没有用人身指责延长争论，而是将讨论带回有记录的事实。","targetForm":"controversy","senseId":"source-n-4","sourceSenseId":"n-4"}]},"confident":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"有信心的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"有把握的"}],"examples":[{"sentence":"After revising the proposal twice, Mei felt confident enough to present it to the committee.","translation":"将提案修改两遍后，梅觉得自己有足够信心把它提交给委员会。","targetForm":"confident","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Although he was confident in his evidence, he invited colleagues to challenge his conclusion.","translation":"尽管他对自己的证据很有信心，他仍邀请同事质疑自己的结论。","targetForm":"confident","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Regular practice made the interns more confident when explaining complex ideas to clients.","translation":"经常练习使实习生在向客户解释复杂观点时更加自信。","targetForm":"confident","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The engineers were confident that the bridge could withstand the predicted flood because the design had been independently tested.","translation":"由于该设计已接受独立测试，工程师确信这座桥能够承受预测中的洪水。","targetForm":"confident","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"Only when the records were complete could the auditor be confident of the final total.","translation":"只有在记录完整时，审计员才能确信最终总额无误。","targetForm":"confident","senseId":"source-adj-2","sourceSenseId":"adj-2"}]},"collar":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"衣领"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"颈圈"}],"examples":[{"sentence":"When the shirt collar became frayed, she decided to replace it rather than discard the entire garment.","translation":"当衬衫领子磨损时，她决定更换领子而不是丢弃整件衣服。","targetForm":"collar","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"A crisp white collar, which contrasts sharply with a dark suit, is a classic symbol of corporate attire.","translation":"与深色西装形成鲜明对比的挺括白领，是职业装的经典标志。","targetForm":"collar","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because the dog's collar was too loose, it slipped off during the walk, which caused a moment of panic.","translation":"因为狗的项圈太松，散步时它滑脱了，这引起了一阵恐慌。","targetForm":"collar","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The detective managed to collar the thief after a high-speed chase through the city streets.","translation":"侦探在城市街道上高速追逐后，终于抓住了小偷。","targetForm":"collar","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Iron the inside of collars first, and then the outside.","translation":"先熨烫领子的里面，然后是外面。","targetForm":"collars","senseId":"source-n-1","sourceSenseId":"n-1"}]},"corner":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"转角"}],"examples":[{"sentence":"When the goalkeeper touched the ball, the referee awarded the other team a corner kick.","translation":"守门员用手碰到了球，裁判给了对方一个角球。","targetForm":"corner","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"When you are driving, you should slow down on corners.","translation":"当您开车的时候，应该在转弯处减速。","targetForm":"corners","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"As everyone stood guard silently, someone ran to the corner of the street and called over a police officer.","translation":"默默守护中，有人跑到街头，叫来了协警。","targetForm":"corner","senseId":"source-n-2","sourceSenseId":"n-2"}]},"complete":{"senseGroups":[{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"完成的"}],"examples":[{"sentence":"That is what it will take, however, to complete the unfinished business of the movement for women’s equality.","translation":"但这是完成妇女平等的未竟事业所必须完成的任务。","targetForm":"complete","senseId":"source-adj-3","sourceSenseId":"adj-3"}]},"complaint":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"控诉"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"抱怨"}],"examples":[{"sentence":"If I do not get the item this week, I will make a complaint to PayPal.","translation":"如果本周我收不到货，我就向paypal投诉。","targetForm":"complaint","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"An increase in customer complaints may indicate that business is declining.","translation":"顾客投诉量增加，可能代表生意正在走下坡。","targetForm":"complaints","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"An increase in customer complaints could signal a decline in business.","translation":"顾客投诉量增加，可能代表生意正在走下坡。","targetForm":"complaints","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"An increase in customer complaints might mean business is going downhill.","translation":"顾客投诉量增加，可能代表生意正在走下坡。","targetForm":"complaints","senseId":"source-n-2","sourceSenseId":"n-2"}]},"costume":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"服装"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"装束"}],"examples":[{"sentence":"The costume used natural fibres and simple fastenings so that performers could move easily during the outdoor show.","translation":"这套戏服采用天然纤维和简单扣件，让表演者在户外演出中能轻松活动。","targetForm":"costume","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Although the costume looked historical, the designer chose modern fabric to withstand repeated use on stage.","translation":"尽管戏服看起来具有历史感，设计师仍选择现代面料来承受舞台上的反复使用。","targetForm":"costume","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The museum displayed each costume beside photographs showing how it appeared in the original production.","translation":"博物馆把每套戏服陈列在照片旁，展示它们在原始演出中的样子。","targetForm":"costume","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Before the parade, volunteers repaired the costume details that had become loose during the previous rehearsal.","translation":"游行前，志愿者修复了上次排练时松动的服装细节。","targetForm":"costume","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"A carefully researched costume can reveal social status, occupation, and local materials without relying on spoken explanation.","translation":"经过仔细考证的服装无需依赖口头说明，也能揭示社会地位、职业和本地材料。","targetForm":"costume","senseId":"source-n-1","sourceSenseId":"n-1"}]},"complement":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"补足物"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"补语"}],"examples":[{"sentence":"Finally, the International Import Expo will complement China’s other measures to liberalize its market, including lower entry barriers for foreign financial firms.","translation":"最后，国际进口博览会将成为中国其他开放市场措施（包括降低外国金融公司的准入门槛）的补充。","targetForm":"complement","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"In grammar, a subject complement follows a linking verb to describe the subject, which is essential for sentence clarity.","translation":"在语法中，主语补足语跟在系动词之后描述主语，这对句子清晰度至关重要。","targetForm":"complement","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"While the new policy aims to boost economic growth, it must complement environmental protection efforts.","translation":"虽然新政策旨在促进经济增长，但它必须与环境保护工作相辅相成。","targetForm":"complement","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"A balanced diet should include vegetables that complement the nutritional value of staple foods.","translation":"均衡的饮食应包括能补充主食营养价值的蔬菜。","targetForm":"complement","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The online resources are designed to complement the textbook, thereby enhancing the learning experience.","translation":"这些在线资源旨在补充教科书，从而提升学习体验。","targetForm":"complement","senseId":"source-n-1","sourceSenseId":"n-1"}]},"compulsory":{"senseGroups":[{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"义务的"},{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"被强制的"}],"examples":[{"sentence":"Although the seminar is compulsory, students may choose which research question they will investigate during the term.","translation":"尽管这门研讨课是必修的，学生仍可选择本学期要研究的问题。","targetForm":"compulsory","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"The policy made safety training compulsory for new staff before they could enter the laboratory.","translation":"该政策规定，新员工进入实验室前必须接受安全培训。","targetForm":"compulsory","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Because attendance was compulsory, the organisers provided an online alternative for participants who lived far away.","translation":"由于必须参加，组织者为住得较远的参与者提供了线上替代方案。","targetForm":"compulsory","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The committee questioned whether compulsory reporting would improve transparency without creating unnecessary administrative work.","translation":"委员会质疑强制报告是否能提高透明度，同时又不会造成不必要的行政工作。","targetForm":"compulsory","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Compulsory schooling expanded access to education, while later reforms focused on improving the quality of teaching.","translation":"义务教育扩大了受教育机会，而后续改革着重于提高教学质量。","targetForm":"compulsory","senseId":"source-adj-3","sourceSenseId":"adj-3"}]},"conversation":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"交谈"},{"id":"source-n-5","partOfSpeech":"n.","sourceSenseIds":["n-5"],"sense":"社交","contextReviewed":true}],"examples":[{"sentence":"A productive conversation begins with careful listening, because people are more willing to explain ideas when they feel heard.","translation":"富有成效的交谈始于认真倾听，因为感到被倾听时，人们更愿意解释自己的想法。","targetForm":"conversation","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Although the conversation became difficult, both managers avoided personal criticism and returned to the evidence.","translation":"尽管谈话变得困难，两位经理都避免了人身批评，并回到证据本身。","targetForm":"conversation","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The documentary sparked a national conversation about how cities could provide affordable housing without displacing residents.","translation":"这部纪录片引发了一场全国性讨论：城市如何在不迫使居民迁离的情况下提供可负担住房。","targetForm":"conversation","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"During the reception, conversation moved easily between literature, travel, and the challenges of public service.","translation":"招待会上，大家轻松地谈到文学、旅行以及公共服务面临的挑战。","targetForm":"conversation","senseId":"source-n-5","sourceSenseId":"n-5"},{"sentence":"The tutor encouraged conversation in English so that quieter students could practise expressing disagreement politely.","translation":"导师鼓励用英语交谈，以便较安静的学生练习礼貌地表达不同意见。","targetForm":"conversation","senseId":"source-n-3","sourceSenseId":"n-3"}]},"composition":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"组成"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"作文"}],"examples":[{"sentence":"Unfortunately, however, while the direction of Africa’s trade may be changing, its composition – raw-material exports and manufactured imports – is not.","translation":"然而不幸的是，虽然非洲贸易的整体风向已经转变，但其内部构成 — — 原材料出口和制成品进口 — — 却没有改变。","targetForm":"composition","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Her composition is very good except for a few errors in spelling.","translation":"她的作文作得十分好，只不过有几个字拼错了。","targetForm":"composition","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Your composition is very good, and it has few mistakes.","translation":"你的作文非常好，而且错误很少。","targetForm":"composition","senseId":"source-n-1","sourceSenseId":"n-1"}]},"commend":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"嘉奖"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"委托给"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"推荐"}],"examples":[{"sentence":"The panel commended the students for revising their design after the first experiment revealed unexpected weaknesses.","translation":"首次实验暴露出意外弱点后，评审小组表扬学生修改了设计。","targetForm":"commended","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Although the report criticised several decisions, it commended the staff who had identified the risk early.","translation":"尽管报告批评了若干决定，它仍表扬了及早发现风险的员工。","targetForm":"commended","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Before leaving the post, the curator commended the collection to a colleague with experience in conservation.","translation":"离职前，馆长把这批藏品委托给一位有文物保护经验的同事。","targetForm":"commended","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The librarian commended the reference book to anyone who needed a reliable introduction to environmental law.","translation":"图书管理员向所有需要可靠环境法入门读物的人推荐了这本参考书。","targetForm":"commended","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"Its clear evidence and modest cost commend the proposal as a practical starting point for further discussion.","translation":"清晰的证据和适中的成本使该提案值得作为进一步讨论的务实起点。","targetForm":"commend","senseId":"source-v-3","sourceSenseId":"v-3"}]},"compress":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"压缩"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"压紧"}],"examples":[{"sentence":"The new software can compress a terabyte of data into a few gigabytes, thereby revolutionizing storage solutions.","translation":"这款新软件可以将一太字节的数据压缩到几千兆字节，从而彻底改变了存储解决方案。","targetForm":"compress","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Although modern algorithms can compress video without visible quality loss, the process requires significant computing power.","translation":"尽管现代算法可以压缩视频而无明显质量损失，但该过程需要大量的计算能力。","targetForm":"compress","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"When you compress a spring, it stores potential energy that can be released to perform work.","translation":"当你压缩弹簧时，它储存了势能，这些势能可以释放出来做功。","targetForm":"compress","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"To ensure efficient data transmission, engineers compress large files before sending them over the network.","translation":"为了确保高效的数据传输，工程师在通过网络发送之前压缩大文件。","targetForm":"compress","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Because the report was too lengthy, the editor had to compress it into a concise summary for the executive board.","translation":"由于报告太长，编辑不得不将其压缩成一份简洁的摘要供执行委员会使用。","targetForm":"compress","senseId":"source-v-1","sourceSenseId":"v-1"}]},"cope":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"应付"}],"examples":[{"sentence":"After Tom lost his job, he started to gamble to cope with his depression.","translation":"汤姆失业后，为了排遣郁闷的心情而开始了赌博。","targetForm":"cope","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Gender norms should not dictate how individuals cope with and process their emotions.","translation":"性别规范不应该规定个人如何面对或处理自己的情绪。","targetForm":"cope","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The problem is how we cope with the present difficulties.","translation":"问题是我们如何应付目前的困难。","targetForm":"cope","senseId":"source-v-2","sourceSenseId":"v-2"}]},"coil":{"senseGroups":[{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"卷"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"盘绕"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"线圈"}],"examples":[{"sentence":"A single coil of barbed wire, if improperly installed, can pose a serious hazard to wildlife.","translation":"单卷带刺铁丝网如果安装不当，会对野生动物构成严重危害。","targetForm":"coil","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"She carefully wound the garden hose into a neat coil, because a tangled hose is difficult to store.","translation":"她小心地将花园水管盘成整齐的一卷，因为缠绕的水管难以存放。","targetForm":"coil","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"The sculptor shaped a coil of clay into an elegant vase, which was then fired in a kiln.","translation":"雕塑家将一卷黏土塑造成优雅的花瓶，随后放入窑中烧制。","targetForm":"coil","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"When threatened, the python will coil tightly around its prey, thereby cutting off circulation.","translation":"当受到威胁时，蟒蛇会紧紧盘绕猎物，从而阻断其血液循环。","targetForm":"coil","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The technician replaced the damaged coil, which had caused the transformer to overheat.","translation":"技术员更换了损坏的线圈，该线圈曾导致变压器过热。","targetForm":"coil","senseId":"source-n-1","sourceSenseId":"n-1"}]},"counter":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"计算器"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"柜台"}],"examples":[{"sentence":"Because the initial plan faced strong opposition, the team developed a counter proposal to address the concerns.","translation":"由于最初的计划遭到强烈反对，团队制定了一个反提案来解决这些担忧。","targetForm":"counter","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The digital counter, which records the number of steps taken, helps users monitor their daily physical activity.","translation":"数字计数器记录行走的步数，帮助用户监测日常身体活动。","targetForm":"counter","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The government implemented a counter inflation policy, thereby stabilizing the economy and restoring public confidence.","translation":"政府实施了反通货膨胀政策，从而稳定了经济并恢复了公众信心。","targetForm":"counter","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the customer waited patiently at the counter, the cashier was busy restocking shelves.","translation":"尽管顾客在柜台前耐心等待，但收银员正忙于补货。","targetForm":"counter","senseId":"source-n-3","sourceSenseId":"n-3"}]},"contemporary":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"同时代的人"}],"examples":[{"sentence":"The level of education of contemporary people is far higher than it has been in the past.","translation":"现在的人教育程度比以前高得多。","targetForm":"contemporary","senseId":"source-n-1","sourceSenseId":"n-1"}]},"couple":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"夫妇"}],"examples":[{"sentence":"Older couples often appreciate cash more than gifts because they neither need nor have room for them.","translation":"年纪大的夫妻往往喜欢礼金胜于礼物, 因为他们既不需要礼物也没有空间放礼物。","targetForm":"couples","senseId":"source-n-2","sourceSenseId":"n-2"}]},"compose":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"写作"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"组成"}],"examples":[{"sentence":"Shizuko composed a poem about the change of the seasons.","translation":"志津子写了一首关于季节变化的诗。","targetForm":"composed","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The committee is composed of three men and seven women.","translation":"委员会是由三男七女组成的。","targetForm":"composed","senseId":"source-v-1","sourceSenseId":"v-1"}]},"comparable":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"可比较的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"比得上的"}],"examples":[{"sentence":"The two surveys are comparable because they asked the same questions of similar groups during the same period.","translation":"这两项调查具有可比性，因为它们在同一时期向相似群体提出了相同问题。","targetForm":"comparable","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Before comparing results, the researchers checked that the samples were comparable in age, size, and location.","translation":"比较结果前，研究人员检查了样本在年龄、大小和地点上是否可比。","targetForm":"comparable","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Although the schools have different histories, their funding levels are broadly comparable when adjusted for student numbers.","translation":"尽管这些学校历史不同，按学生人数调整后，它们的经费水平大体可比。","targetForm":"comparable","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The new model offers performance comparable to that of larger machines while using far less energy.","translation":"新型号的性能可与更大型机器媲美，同时耗能少得多。","targetForm":"comparable","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"Few local venues are comparable to the restored theatre, whose acoustics make it suitable for both speech and music.","translation":"本地很少有场馆可与修复后的剧院相媲美；其声学效果适合演讲和音乐。","targetForm":"comparable","senseId":"source-adj-2","sourceSenseId":"adj-2"}]},"comparison":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"比较"}],"examples":[{"sentence":"A brief history of the concept, and a comparison with another term that also became discredited by overuse, helps to explain what happened.","translation":"简要回顾一下这个概念的历史，并且把它同另一个因滥用而没落的词作一番比较，有助于解释上述现象。","targetForm":"comparison","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"In comparison, shale gas in the US has created an estimated 600,000 jobs that are generating about $100 billion in added GDP and almost $20 billion in public revenue.","translation":"比较而言，页岩气在美国创造了约60万个就业岗位、增加了1000亿美元的GDP和近200亿美元的公共收入。","targetForm":"comparison","senseId":"source-n-1","sourceSenseId":"n-1"}]},"confront":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"使面对"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"遭遇"}],"examples":[{"sentence":"It is the ideology, not just the acts of extremism, that must be confronted.","translation":"我们必须面对的是这一意识形态，而不是恐怖主义行为。","targetForm":"confronted","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Turkey is currently confronting the limits of its possibilities, while the EU finds that it can do very little in this region without Turkey.","translation":"此外，在欧洲的南方近邻，即地中海地区，新风险正在北非和撒哈拉地区迅猛崛起，包括基地组织对马里北部的威胁。","targetForm":"confronting","senseId":"source-v-3","sourceSenseId":"v-3"}]},"coin":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"硬币"}],"examples":[{"sentence":"I found a pot in which there were several old coins.","translation":"我找到一个装有几枚古钱币的锅子。","targetForm":"coins","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The coin toss decides who will kick off the match.","translation":"裁判抛硬币来决定谁来开球。","targetForm":"coin","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The five yuan coins are brass, and the ten yuan coins are made out of bronze.","translation":"5元硬币是黄铜做的，10元硬币是青铜做的。","targetForm":"coins","senseId":"source-n-1","sourceSenseId":"n-1"}]},"compass":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"指南针"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"范围"}],"examples":[{"sentence":"A strong moral compass is essential for leaders, as it guides them through complex ethical dilemmas.","translation":"坚定的道德指南针对领导者至关重要，因为它能引导他们度过复杂的道德困境。","targetForm":"compass","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because the compass needle aligns with the Earth's magnetic field, it reliably indicates the north-south direction.","translation":"因为指南针的指针与地球磁场对齐，所以它能可靠地指示南北方向。","targetForm":"compass","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the compass was invented centuries ago, it remains a fundamental tool for outdoor navigation.","translation":"尽管指南针是几个世纪前发明的，但它仍然是户外导航的基本工具。","targetForm":"compass","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"While the compass is simple in design, its impact on exploration and trade was profound.","translation":"虽然指南针设计简单，但它对探险和贸易的影响却是深远的。","targetForm":"compass","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The project fell within the compass of the committee's responsibilities, which included environmental oversight.","translation":"该项目属于委员会的职责范围，其中包括环境监督。","targetForm":"compass","senseId":"source-n-2","sourceSenseId":"n-2"}]},"combination":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"组合"}],"examples":[{"sentence":"The combination of clear rules and patient feedback helped the new volunteers learn quickly.","translation":"明确的规则与耐心的反馈相结合，帮助新志愿者迅速学习。","targetForm":"combination","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"A combination of heavy rain and poor drainage caused the basement to flood overnight.","translation":"暴雨与排水不良共同导致地下室一夜之间被淹。","targetForm":"combination","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The lock opens only when the correct combination is entered in the right order.","translation":"只有按正确顺序输入正确组合，锁才能打开。","targetForm":"combination","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Their combination of practical experience and academic training made the project more credible.","translation":"他们把实践经验与学术训练结合起来，使项目更可信。","targetForm":"combination","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"No single factor explains the result; it emerged from a combination of decisions made over several years.","translation":"没有单一因素能解释这一结果，它源于数年间作出的一系列决定的组合。","targetForm":"combination","senseId":"source-n-1","sourceSenseId":"n-1"}]},"consult":{"senseGroups":[{"id":"source-v-5","partOfSpeech":"v.","sourceSenseIds":["v-5"],"sense":"向...请教"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"商讨"}],"examples":[{"sentence":"You should consult with a pharmacist before buying that medicine.","translation":"你在买这药之前应该问一下药剂师的建议。","targetForm":"consult","senseId":"source-v-5","sourceSenseId":"v-5"},{"sentence":"He's already retired but is often asked by them to consult.","translation":"已经退休了，但还常常被他们请去做顾问。","targetForm":"consult","senseId":"source-v-1","sourceSenseId":"v-1"}]},"colleague":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"同事"}],"examples":[{"sentence":"He and a colleague who went to China later translated The New Testament into Chinese.","translation":"他跟一个去中国的同事后来把圣经中的新约翻译成中文。","targetForm":"colleague","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"My colleague and I do the same job, but he was promised a promotion in a very short while.","translation":"我和我别的同事做同样的事情，但是得到了能在很短时间内得到晋升的承诺。","targetForm":"colleague","senseId":"source-n-1","sourceSenseId":"n-1"}]},"coarse":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"粗糙的"},{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"粗俗的"},{"id":"source-other-1","partOfSpeech":"计算机","sourceSenseIds":["other-1"],"sense":"粗略的；低分辨率的","contextReviewed":true}],"examples":[{"sentence":"The path was covered with coarse gravel, so the volunteers wore sturdy shoes while carrying boxes to the site.","translation":"小路铺满粗砾石，因此志愿者搬箱子到现场时穿了结实的鞋。","targetForm":"coarse","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Although the fabric felt coarse at first, it proved durable enough for the tents used throughout the long field season.","translation":"尽管这种布料起初手感粗糙，它仍足够耐用，可供整个漫长的野外季使用。","targetForm":"coarse","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The editor removed the coarse language because it distracted from the argument and did not suit the intended audience.","translation":"编辑删去了粗俗语言，因为它会分散对论点的注意，也不适合目标读者。","targetForm":"coarse","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"Before judging the layout, the designer created a coarse version of the map to test which information mattered most.","translation":"在评估布局前，设计师先制作了地图的粗略版本，以测试哪些信息最重要。","targetForm":"coarse","senseId":"source-other-1","sourceSenseId":"other-1"},{"sentence":"The satellite produced a coarse image at first, but later passes supplied the detail needed for the final analysis.","translation":"卫星起初生成低分辨率图像，但后续飞越提供了最终分析所需的细节。","targetForm":"coarse","senseId":"source-other-1","sourceSenseId":"other-1"}]},"complain":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"抱怨"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"抗议"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"控诉"}],"examples":[{"sentence":"Residents complained that the timetable changed too often, making it difficult to plan journeys to work.","translation":"居民抱怨时刻表变化过于频繁，使他们难以规划上班行程。","targetForm":"complained","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Although customers may complain about delays, a clear explanation often prevents frustration from becoming a larger dispute.","translation":"尽管顾客可能抱怨延误，清晰解释往往能防止挫折感演变为更大争端。","targetForm":"complain","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The students complained to the council when the promised study space was removed without consultation.","translation":"承诺的学习空间未经协商就被取消时，学生向市议会提出抗议。","targetForm":"complained","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Because the organisation had ignored earlier warnings, local groups complained publicly about the decision.","translation":"由于该组织忽视了早先警告，当地团体公开抗议这一决定。","targetForm":"complained","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The report complained of serious gaps in the record-keeping system and called for an independent review.","translation":"报告控诉记录保存系统存在严重缺口，并呼吁进行独立审查。","targetForm":"complained","senseId":"source-v-3","sourceSenseId":"v-3"}]},"coach":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"教练"}],"examples":[{"sentence":"The players sat in the locker room while they listened to their coach speak.","translation":"球员们坐在更衣室里听教练讲话。","targetForm":"coach","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The players sat and listened to their coach give them a pep talk in the changing rooms.","translation":"球员们坐在更衣室，听教练给他们打气。","targetForm":"coach","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Jack’s coach decided to keep him on the bench for being late to training.","translation":"由于训练迟到，杰克的教练决定把他留在替补席。","targetForm":"coach","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The manager and coach stood on the touchline shouting out instructions to their team.","translation":"足球教练站在边线上对自己的队伍喊出指令。","targetForm":"coach","senseId":"source-n-2","sourceSenseId":"n-2"}]},"confuse":{"senseGroups":[{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"[法] 混淆","contextReviewed":true},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"使困惑"}],"examples":[{"sentence":"This is an example of confusing two things that have a common cause with one thing that causes another.","translation":"这显然是将属并列关系的两件事误解成为因果关系了。","targetForm":"confusing","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"That was the part that Tom and I were most confused about.","translation":"这是我和汤姆最困惑的部分。","targetForm":"confused","senseId":"source-v-3","sourceSenseId":"v-3"}]},"copy":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"副本"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"一册"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"摹仿"}],"examples":[{"sentence":"Before submitting the final report, the editor carefully reviewed the copy for any factual errors, thereby ensuring its accuracy.","translation":"在提交最终报告之前，编辑仔细审阅了文稿，查找任何事实错误，从而确保了其准确性。","targetForm":"copy","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Please submit a clean copy of your manuscript without any handwritten corrections, because the publisher requires a digital version.","translation":"请提交一份干净的手稿副本，不要有任何手写修改，因为出版社要求电子版。","targetForm":"copy","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The library holds a rare copy of the first edition, which scholars often request to examine, although access is restricted.","translation":"图书馆藏有一本珍稀的第一版副本，学者们经常请求查阅，尽管获取受限。","targetForm":"copy","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Although the painting is a copy, it faithfully reproduces the original's intricate details and vibrant colors, which makes it highly valued.","translation":"尽管这幅画是复制品，但它忠实地再现了原作的精细细节和鲜艳色彩，这使得它备受珍视。","targetForm":"copy","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The marketing team prepared compelling copy for the new product launch to attract potential customers, while also highlighting its unique features.","translation":"营销团队为新产品发布准备了引人注目的广告文案，以吸引潜在客户，同时也突出了其独特功能。","targetForm":"copy","senseId":"source-n-1","sourceSenseId":"n-1"}]},"colony":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"殖民地"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"移民队"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"菌落","contextReviewed":true}],"examples":[{"sentence":"The course examined how the former colony rebuilt its legal system after independence.","translation":"这门课程探讨了这个前殖民地在独立后如何重建法律体系。","targetForm":"colony","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"A small artists' colony developed near the coast because the light attracted painters from several cities.","translation":"海岸附近形成了一个小型艺术家聚居地，因为那里的光线吸引了几座城市的画家。","targetForm":"colony","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The biologist counted each bacterial colony before comparing the effects of the two cleaning methods.","translation":"生物学家先计数每个细菌菌落，再比较两种清洁方法的效果。","targetForm":"colony","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"A colony of seabirds returned to the island after the nesting area was protected from disturbance.","translation":"筑巢区受到保护、免受干扰后，一群海鸟回到了岛上。","targetForm":"colony","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The lab recorded the size of every colony growing on the plates over three consecutive days.","translation":"实验室连续三天记录培养皿上每个菌落的大小。","targetForm":"colony","senseId":"source-n-3","sourceSenseId":"n-3"}]},"column":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"专栏"}],"examples":[{"sentence":"This column draws on a Bruegel report co-authored with André Sapir and Guntram Wolff.","translation":"本专栏改编自与André Sapir和Guntram Wolff合作的Bruegel报告。","targetForm":"column","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The views expressed in this column are the author’s own, and do not represent those of the National Bank of Abu Dhabi.","translation":"本专栏仅代表作者个人观点，不代表阿布扎比国民银行观点。","targetForm":"column","senseId":"source-n-1","sourceSenseId":"n-1"}]},"coffee":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"咖啡"}],"examples":[{"sentence":"Mary told me that she drinks at least three cups of coffee a day.","translation":"玛丽告诉我她每天至少喝三杯咖啡。","targetForm":"coffee","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Let's go drink a cup of coffee at that coffee shop over there.","translation":"我们去那间咖啡店喝杯咖啡吧。","targetForm":"coffee","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"If you drink instant coffee you do not need a coffee pot.","translation":"如果你喝速溶咖啡，就不需要咖啡壶了。","targetForm":"coffee","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The coffee enabled me to stay awake during the dull concert.","translation":"咖啡让我在沉闷的音乐会中保持清醒。","targetForm":"coffee","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"He brought me coffee, when I had asked for tea.","translation":"我要的是茶，而他却给了我一杯咖啡。","targetForm":"coffee","senseId":"source-n-1","sourceSenseId":"n-1"}]},"collect":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"收集"},{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"搜集"}],"examples":[{"sentence":"Researchers collected water samples from the river after the storm.","translation":"暴风雨过后，研究人员从河中采集了水样。","targetForm":"collected","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Please collect your ticket from the desk before entering the hall.","translation":"进入大厅前，请到服务台领取你的票。","targetForm":"collect","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The museum collects local photographs to preserve the town's history.","translation":"博物馆收集当地照片，以保存小镇的历史。","targetForm":"collects","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Children enjoy collecting leaves of different shapes in autumn.","translation":"孩子们喜欢在秋天收集形状各异的树叶。","targetForm":"collecting","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The library will collect suggestions before choosing next year's books.","translation":"图书馆会在选择明年书目之前征集建议。","targetForm":"collect","senseId":"source-v-4","sourceSenseId":"v-4"}]},"constitution":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"宪法"}],"examples":[{"sentence":"Unfortunately, as things stand, this is a referendum that Blair will not win, because all polls show a large and solid majority against the European Constitution.","translation":"不幸的是，就当前情况来看，这是一场布莱尔不会赢得的全民投票，因为所有的选票都显示绝大多数人坚决反对欧洲宪法。","targetForm":"constitution","senseId":"source-n-2","sourceSenseId":"n-2"}]},"cotton":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"棉花"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"理解"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"有好感"}],"examples":[{"sentence":"The museum displayed cotton cloth woven by local families before large factories changed the industry.","translation":"博物馆展出了大型工厂改变行业前由当地家庭织成的棉布。","targetForm":"cotton","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Cotton plants require careful management because pests can damage the crop before harvest.","translation":"棉花植株需要细致管理，因为害虫会在收获前损害作物。","targetForm":"cotton","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The two researchers cottoned on quickly once they realised that they were asking the same question.","translation":"两位研究者意识到自己在问同一个问题后，很快就明白了彼此的意思。","targetForm":"cottoned","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"She did not cotton to the proposal because it ignored the needs of residents with limited mobility.","translation":"她不喜欢这项提案，因为它忽视了行动不便居民的需求。","targetForm":"cotton","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The nurse placed cotton over the small cut before covering it with a clean bandage.","translation":"护士先在小伤口上放棉花，再用干净绷带覆盖。","targetForm":"cotton","senseId":"source-n-1","sourceSenseId":"n-1"}]},"confirm":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"证实"}],"examples":[{"sentence":"This afternoon, the World Health Organization confirmed three thousand new cases of coronavirus, among which a hundred people died.","translation":"今天下午，世界卫生组织证实了3000个新型冠状病毒病例，其中有100人死亡。","targetForm":"confirmed","senseId":"source-v-1","sourceSenseId":"v-1"}]},"competent":{"senseGroups":[{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"胜任的"},{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"能干的"},{"id":"source-adj-5","partOfSpeech":"adj.","sourceSenseIds":["adj-5"],"sense":"有权的","contextReviewed":true}],"examples":[{"sentence":"A competent editor improves the structure of an article without removing the writer's own voice.","translation":"称职的编辑会改善文章结构，而不会抹去作者自己的声音。","targetForm":"competent","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"The school needs competent staff who can respond calmly when a child requires urgent help.","translation":"学校需要能干的员工，能在孩子急需帮助时冷静应对。","targetForm":"competent","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"She became competent in the software after practising with small tasks instead of reading instructions once.","translation":"她通过反复完成小任务，而不是只读一遍说明，逐渐熟练掌握了软件。","targetForm":"competent","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"Only a competent authority may approve the change because the project affects protected land.","translation":"由于项目影响受保护土地，只有有权机构才能批准这项变更。","targetForm":"competent","senseId":"source-adj-5","sourceSenseId":"adj-5"},{"sentence":"The team was competent to carry out the inspection because every member had completed the required training.","translation":"团队有能力进行检查，因为每位成员都完成了所需培训。","targetForm":"competent","senseId":"source-adj-2","sourceSenseId":"adj-2"}]},"content":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"内容"}],"examples":[{"sentence":"While video platforms do not explicitly ban such content, works of this type will have their traffic restricted.","translation":"虽然视频平台没有明确禁止此类内容，但这种类型的作品的流量会被限制。","targetForm":"content","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Please don't be so surprised that I'm speaking this language and listen to the content of what I'm actually saying.","translation":"请不要惊讶我讲这种语言，请注意我讲的内容。","targetForm":"content","senseId":"source-n-1","sourceSenseId":"n-1"}]},"compel":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"迫使"}],"examples":[{"sentence":"Despite all of this, there were compelling reasons to believe that Modi’s government would keep Rajan on board.","translation":"尽管如此，人们仍有充分的理由相信莫迪政府会让拉詹留任。","targetForm":"compelling","senseId":"source-v-2","sourceSenseId":"v-2"}]},"command":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"控制"}],"examples":[{"sentence":"She has a good command of English though she was brought up in Japan.","translation":"虽然她在日本被抚养长大，但是她精通英语。","targetForm":"command","senseId":"source-n-3","sourceSenseId":"n-3"}]},"come":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"来"}],"examples":[{"sentence":"DENVER – Patience might be a virtue, but not necessarily when it comes to American foreign policy.","translation":"丹佛 — — 耐心是一种美德，但在美国外交政策上绝非如此。","targetForm":"comes","senseId":"source-v-2","sourceSenseId":"v-2"}]},"concept":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"概念"}],"examples":[{"sentence":"A brief history of the concept, and a comparison with another term that also became discredited by overuse, helps to explain what happened.","translation":"简要回顾一下这个概念的历史，并且把它同另一个因滥用而没落的词作一番比较，有助于解释上述现象。","targetForm":"concept","senseId":"source-n-2","sourceSenseId":"n-2"}]},"commit":{"senseGroups":[{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"使承担义务"}],"examples":[{"sentence":"It is likely that Pachauri is right and Gore is wrong: neither China nor India will commit to significant cuts without a massive payoff.","translation":"很可能帕乔里对了而戈尔错了：在没有巨大收益的情况下，中国和印度都不会承诺进行重大的减排。","targetForm":"commit","senseId":"source-v-4","sourceSenseId":"v-4"}]},"convenience":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"便利的事物"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"方便"}],"examples":[{"sentence":"The printer of my company broke down again, so I'm going to the convenience store to copy documents.","translation":"因为公司的打印机又坏了，我要去便利店打印文件。","targetForm":"convenience","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Starting from 2009, supermarkets and convenience stores have been allowed to sell medicines.","translation":"从2009年开始，超市和便利店就可以出售药品了。","targetForm":"convenience","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"I bought meat buns at the convenience store and ate them.","translation":"我在便利店买了肉包吃了。","targetForm":"convenience","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Television has the advantage of providing sports fans with greater convenience.","translation":"电视的优点在于它给体育爱好者提供了更大的方便。","targetForm":"convenience","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"It started raining on my way to the convenience store.","translation":"在我去便利商店的路上，天开始下雨了。","targetForm":"convenience","senseId":"source-n-2","sourceSenseId":"n-2"}]},"conclude":{"senseGroups":[{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"推断"}],"examples":[{"sentence":"As he has done a lot of bad things, we can conclude that he is a bad person.","translation":"因为他做了不少坏事，我们可以断定他不是个好人。","targetForm":"conclude","senseId":"source-v-3","sourceSenseId":"v-3"}]},"collaborate":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"合作"}],"examples":[{"sentence":"The African ground squirrels collaborate and are not aggressive to other mammals.","translation":"非洲地松鼠互帮互助，对其他哺乳动物没有攻击性。","targetForm":"collaborate","senseId":"source-v-1","sourceSenseId":"v-1"}]},"compare":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"比较"},{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"相比"}],"examples":[{"sentence":"Compare that to the $180 billion cost of implementing the Kyoto Protocol, which will have virtually no effect.","translation":"让我们把这笔费用与实施《东京议定书》将要耗费的1800亿美元作一下比较，何况实施《东京议定书》实际上并不会起到什么作用。","targetForm":"compare","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Compared with the tension that exists in Muslim communities across Europe, America’s Muslims are a more contented lot.","translation":"与遍布欧洲的穆斯林社区存在的紧张现状相比，美国的穆斯林可谓更为心满意足。","targetForm":"compared","senseId":"source-v-4","sourceSenseId":"v-4"}]},"concentrate":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"浓缩"}],"examples":[{"sentence":"If you concentrate all your energies on the study of English, you will master the language.","translation":"你如果能把全副精力放进去，要学会英文并不是难事。","targetForm":"concentrate","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The average man fails not because he lacks ability, but because he lacks ability to concentrate.","translation":"通常人们失败并非能力不足，而是不够专注。","targetForm":"concentrate","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"I can't concentrate on my work because of the noise.","translation":"由于噪音，我无法集中精力工作了。","targetForm":"concentrate","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"As North Korea displays aggression, South Korea concentrates its forces near the border.","translation":"韩国随着朝鲜的外患而在边界附近集结军队。","targetForm":"concentrates","senseId":"source-n-1","sourceSenseId":"n-1"}]},"construct":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"建造"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"构造"}],"examples":[{"sentence":"After reading his books I feel I can construct a house.","translation":"读完他的书后，我觉得我可以构建一栋房子。","targetForm":"construct","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The purpose of criticism is to construct, not to destroy.","translation":"批评的目的是建设而不是破坏。","targetForm":"construct","senseId":"source-v-1","sourceSenseId":"v-1"}]},"compute":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"计算"}],"examples":[{"sentence":"Now we are on the cusp of another major convergence: big data, machine learning, and increased computing power will soon make artificial intelligence, or AI, ubiquitous.","translation":"现在我们正站在另一次大规模融合的风口浪尖上：大数据、机器学习和不断提高的计算能力将很快使人工智能（AI）无处不在。","targetForm":"computing","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"It's possible to branch out from computing to jobs in banking, accountancy and so on.","translation":"有可能将电脑工作扩展到银行业务, 会计业务等等。","targetForm":"computing","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Some of my classmates are pure noobs; they know nothing about computing sciences.","translation":"我的一些同学真是菜鸟，他们一点都不懂计算机。","targetForm":"computing","senseId":"source-v-1","sourceSenseId":"v-1"}]},"comparative":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"比较的"}],"examples":[{"sentence":"Clearly, a new approach is needed – one that capitalizes on the comparative advantages of the private sector, state authorities, and the federal government.","translation":"显然，我们需要新方针 — — 利用私人部门、州有关部门和联邦政府的比较优势的方针。","targetForm":"comparative","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"I study comparative religion in the arts faculty of the University of Turku.","translation":"我在图尔库大学文化系学习宗教比较学。","targetForm":"comparative","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"collective":{"senseGroups":[{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"共同的"},{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"集体的"}],"examples":[{"sentence":"History suggests that collective negotiation about currencies and a new approach to the issue of reserves are unlikely to succeed.","translation":"历史似乎意味着，有关汇率和储备问题新方案的会谈是不太可能成功的。","targetForm":"collective","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"At least two recent examples illustrate the potentially devastating effects of collective mechanisms for protecting savers despite a joint banking regulator.","translation":"至少有两个最近的例子可以说明保护储户的集体机制如何导致灾难性后果，哪怕存在联合银行监管当局。","targetForm":"collective","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Change is possible, but it requires collective action by the international community to challenge the attitudes that lead to violence, oppression, and inequality.","translation":"· 批准并实施所有相关地区和国际条约，并实施禁止针对妇女的暴力的法律，确保暴力行为的有效惩罚。","targetForm":"collective","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"coal":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"煤"}],"examples":[{"sentence":"Poland uses coal for 98% of its electricity production, and South Africa uses coal for about 50% of its electricity production.","translation":"因此，在这种背景下，特别是鉴于现代技术可以帮助以清洁的方式产煤，人们很难不料想发展中国家会开发其丰富的煤炭资源来为其自身发展提供电力。","targetForm":"coal","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Carbon dioxide is a gas that is produced every time a fuel such as coal, oil, or natural gas is burned.","translation":"二氧化碳是燃烧煤、石油或天然气这样的燃料时会产生的气体。","targetForm":"coal","senseId":"source-n-1","sourceSenseId":"n-1"}]},"communication":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"交流"}],"examples":[{"sentence":"Knowing their languages is not enough to communicate effectively, because the methods of communication are determined by their cultures.","translation":"要和他们有效地沟通，只懂得说他们的语言是不够的，因为沟通的方式是由他们的文化来决定的。","targetForm":"communication","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The fact that television frequently limits communication within families is already well known.","translation":"电视限制家庭成员的沟通的事实已经广为人知。","targetForm":"communication","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The fact that television limits communication among family members is already widely known.","translation":"电视限制家庭成员的沟通的事实已经广为人知。","targetForm":"communication","senseId":"source-n-1","sourceSenseId":"n-1"}]},"congress":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"会议"}],"examples":[{"sentence":"Moreover, China’s rulers are focused on the looming 17th Congress of the Communist Party, which could likewise be spoiled by a bloody confrontation in Burma.","translation":"此外，中国的执政者正把精力集中在即将召开的党的十七大上，而这有可能被缅甸发生的血腥冲突所破坏。","targetForm":"congress","senseId":"source-n-2","sourceSenseId":"n-2"}]},"conviction":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"坚信"}],"examples":[{"sentence":"One must have conviction in law, or its existence will be superficial only.","translation":"法律必须被信仰，否则形同虚设。","targetForm":"conviction","senseId":"source-n-3","sourceSenseId":"n-3"}]},"community":{"senseGroups":[{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"共同体"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"社区"}],"examples":[{"sentence":"Europe deserves to prove that it is a real community, one diverse, democratic, spiritual, free, and prosperous.","translation":"欧洲应该证明自己是一个真正的社会，一个多元、民主、高尚、自由和繁荣的社会。","targetForm":"community","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"Compared with the tension that exists in Muslim communities across Europe, America’s Muslims are a more contented lot.","translation":"与遍布欧洲的穆斯林社区存在的紧张现状相比，美国的穆斯林可谓更为心满意足。","targetForm":"communities","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Change is possible, but it requires collective action by the international community to challenge the attitudes that lead to violence, oppression, and inequality.","translation":"· 批准并实施所有相关地区和国际条约，并实施禁止针对妇女的暴力的法律，确保暴力行为的有效惩罚。","targetForm":"community","senseId":"source-n-4","sourceSenseId":"n-4"}]},"construction":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"建筑"}],"examples":[{"sentence":"I have to wear earplugs to drown out all the noise from the construction site next door.","translation":"我不得不戴耳塞来阻隔旁边建筑工地的所有噪音。","targetForm":"construction","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The wood of trees in the pine family is much prized for construction and furniture making.","translation":"松科树木的木材因其优良的品质，在建筑和家具制造领域备受推崇。","targetForm":"construction","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"There is a shortage of good construction timber right now.","translation":"现在正缺良好的建筑木材。","targetForm":"construction","senseId":"source-n-1","sourceSenseId":"n-1"}]},"cost":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"费用"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"代价"}],"examples":[{"sentence":"Compare that to the $180 billion cost of implementing the Kyoto Protocol, which will have virtually no effect.","translation":"让我们把这笔费用与实施《东京议定书》将要耗费的1800亿美元作一下比较，何况实施《东京议定书》实际上并不会起到什么作用。","targetForm":"cost","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"When costs for labor-intensive goods and services became too high in these countries, production was shifted elsewhere.","translation":"如今的开放国际贸易和投资体系使得公司能够把生产放在最有利于其国际竞争力的地方，中国本身也从中获益良多，现在，中国也开始转移劳动密集型产业了。","targetForm":"costs","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"We all want justice, but that justice should not come at the cost of our humanity.","translation":"我们都渴望公正，但那种公正不能以牺牲人性为代价。","targetForm":"cost","senseId":"source-n-1","sourceSenseId":"n-1"}]},"coast":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"海岸"}],"examples":[{"sentence":"Zhejiang Province is located on the southeastern coast of China and belongs to the East China region.","translation":"浙江省地处中国东南沿海，隶属于华东地区。","targetForm":"coast","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The economist and statistician based in Ivory Coast says commercial trade in the region is primarily conducted with France.","translation":"这位常驻科特迪瓦的经济学家兼统计学家表示，该地区的商业贸易主要与法国进行。","targetForm":"coast","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"China, otherwise known as the People's Republic of China, is located in east Asia, on the western coast of the Pacific ocean.","translation":"中国，全名中华人民共和国，位于亚洲东部，太平洋西岸。","targetForm":"coast","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"More than a third of the world population lives near a coast.","translation":"全世界有超过三分之一的人在沿岸地区居住。","targetForm":"coast","senseId":"source-n-1","sourceSenseId":"n-1"}]},"court":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"法院"}],"examples":[{"sentence":"Finally, Trump will nominate conservative justices for the Supreme Court, which has had one vacancy since Justice Antonin Scalia died in February.","translation":"最后，特朗普将提名保守派法官进入最高法院，2月份安东宁·斯卡利亚（Antonin Scalia）法官逝世后，最高法院已经出现了一个空缺。","targetForm":"court","senseId":"source-n-1","sourceSenseId":"n-1"}]},"constant":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"常数"}],"examples":[{"sentence":"Despite Trang's constant affirmations of love, Spenser is still afraid someday she will fall out of love with him.","translation":"尽管庄不断发誓她不变的爱情，斯宾塞仍然害怕有一天她会不爱他了。","targetForm":"constant","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Even though a parameter's value can change, it is treated as a constant, not as a variable.","translation":"尽管参数的值可变，但我们仍把它视为常量，而非变量。","targetForm":"constant","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Lately there have been constant dance rehearsals; Performances will be on Friday and Saturday.","translation":"最近一直在舞蹈排练，周五周六要演出啊。","targetForm":"constant","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Tom found Mary's constant criticism of him hard to cope with.","translation":"汤姆认为和经常批评他的玛丽很难相处。","targetForm":"constant","senseId":"source-n-1","sourceSenseId":"n-1"}]},"communism":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"共产主义"}],"examples":[{"sentence":"The American mission is to eliminate communism from the world.","translation":"美国的任务是将共产主义从世界上消除。","targetForm":"communism","senseId":"source-n-1","sourceSenseId":"n-1"}]},"convince":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"说服"}],"examples":[{"sentence":"With Russia ostensibly on board, it is up to the US to initiate a transformation in the nuclear-negotiation framework – and that means convincing China to participate.","translation":"因为俄罗斯表面上愿意配合，需要由美国启动核谈判框架的转型工作 — — 这意味着要说服中国参与到谈判过程中。","targetForm":"convincing","senseId":"source-v-1","sourceSenseId":"v-1"}]},"consumption":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"消费"}],"examples":[{"sentence":"That our profligate consumption requires five planets is a catchy story, but it is wrong.","translation":"比约恩·隆姆博格，哥本哈根共识中心的主任，是哥本哈根商学院兼职教授，着有《怀疑主义环保分子并请冷静：怀疑主义环保分子之全球变暖指南 》 。","targetForm":"consumption","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Unless and until US consumption patterns change or a rebounding dollar increases oil production, Americans will bear the brunt of single-currency oil pricing.","translation":"除非并且直到美国人的消费模式发生改变或者美元反弹从而增加石油产量，美国人将首当其冲的受到石油用单一货币计价的影响。","targetForm":"consumption","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The first reason is likely to create a long-term drag on growth: households need to deleverage and save more, which will constrain consumption for years.","translation":"原因之一是：居民家庭需要减少透支，增加储蓄，这就会对拉动消费产生影响，从而会拖经济的后腿。","targetForm":"consumption","senseId":"source-n-1","sourceSenseId":"n-1"}]},"collection":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"(一批)收藏品"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"收集"},{"id":"source-n-6","partOfSpeech":"n.","sourceSenseIds":["n-6"],"sense":"收集品","contextReviewed":true}],"examples":[{"sentence":"Tom was exposed to a wide variety of music as a child through his mother's vast record collection.","translation":"由于母亲收藏了一整屋的唱片，汤姆小时候便有机会接触各种类型的音乐。","targetForm":"collection","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"I don't have a stamp collection, but I have a Japanese postcard collection that I could use as an excuse to invite him.","translation":"我没有集邮，但是却收藏了一堆日本的明信片，我想我可以用这来做借口，邀请他来我家。","targetForm":"collection","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Now Ghouate's village is connected to the world's largest functioning fog collection project, alleviating the need to collect water that fell mainly on women.","translation":"现在，Ghouate 的村庄与世界上最大的功能雾收集项目相连，减轻了主要落在妇女身上的收集水的需要。","targetForm":"collection","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"I would like to have a look at your collection of stamps.","translation":"我想看看您的邮票收藏。","targetForm":"collection","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The spatulas, ramekins, plates, and mugs are all from the collection.","translation":"这些锅铲、烤盅、盘子和马克杯都来自这套集合。","targetForm":"collection","senseId":"source-n-6","sourceSenseId":"n-6"}]},"cool":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"凉爽"}],"examples":[{"sentence":"On a hot summer day, the air conditioner works all day to keep us cool.","translation":"炎炎夏日，空调全天开放让我们保持凉爽。","targetForm":"cool","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"I was quite thirsty and wanted to drink something cool.","translation":"我很渴，想喝点冷饮。","targetForm":"cool","senseId":"source-n-1","sourceSenseId":"n-1"}]},"contribution":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"贡献"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"捐助"}],"examples":[{"sentence":"Her contribution to the study was not just collecting data but also explaining what the figures meant locally.","translation":"她对研究的贡献不仅是收集数据，也包括解释这些数字在当地意味着什么。","targetForm":"contribution","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The library received a contribution from a former student who wanted to support free public programmes.","translation":"图书馆收到一位往届学生的捐款，他希望支持免费的公共项目。","targetForm":"contribution","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Small contributions from many residents paid for the equipment needed to improve the playground.","translation":"许多居民的小额捐助支付了改善游乐场所需的设备费用。","targetForm":"contributions","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The article makes a useful contribution by connecting recent research with the experience of local workers.","translation":"这篇文章把近期研究与当地工人的经验联系起来，作出了有益贡献。","targetForm":"contribution","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Every member made a contribution, so the final presentation reflected more than one point of view.","translation":"每位成员都作出了贡献，因此最终展示反映了不止一种观点。","targetForm":"contribution","senseId":"source-n-3","sourceSenseId":"n-3"}]},"connect":{"senseGroups":[{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"联系"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"连接"}],"examples":[{"sentence":"The short list covers a lot of ground; what connects the targets is the amount of good they will do for people, the planet, and prosperity.","translation":"这份重点清单涉及到众多领域；其中的联系是能为民众、地球和繁荣带来多少好处。","targetForm":"connects","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"If you connect your phone to your PC via USB, you can even transfer files and photos.","translation":"您如果透过 USB 将手机连接到电脑，则甚至可以传输档案和照片。","targetForm":"connect","senseId":"source-v-1","sourceSenseId":"v-1"}]},"comic":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"连环漫画"}],"examples":[{"sentence":"My dad gives me a weekly allowance that I use to buy comics and ice cream.","translation":"我爸爸每周给我零用钱，我会用来买漫画书和冰激凌。","targetForm":"comics","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The comic downloader that I wrote will be released this Sunday.","translation":"我写的漫画下载器本周日就发布。","targetForm":"comic","senseId":"source-n-1","sourceSenseId":"n-1"}]},"convey":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"传达"}],"examples":[{"sentence":"While dreams cannot tell you what will happen to you in reality, they are able to convey your innermost thoughts.","translation":"梦虽然不会告诉你现实中将要发生什么，却能告诉你内心的真实想法。","targetForm":"convey","senseId":"source-v-1","sourceSenseId":"v-1"}]},"country":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"国家"}],"examples":[{"sentence":"In Israel, Obama will encounter a country that has indeed moved, but not toward a missing center.","translation":"奥巴马所面临的问题是以色列正沿着自身的轨道运行，并且离中间路线越来越远。","targetForm":"country","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"When costs for labor-intensive goods and services became too high in these countries, production was shifted elsewhere.","translation":"如今的开放国际贸易和投资体系使得公司能够把生产放在最有利于其国际竞争力的地方，中国本身也从中获益良多，现在，中国也开始转移劳动密集型产业了。","targetForm":"countries","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The unsolved problem is how to reduce those factors pushing people out of their own countries.","translation":"悬而未决的问题是如何遏制推动人们离开祖国的因素。","targetForm":"countries","senseId":"source-n-1","sourceSenseId":"n-1"}]},"confusion":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"混淆"}],"examples":[{"sentence":"Three conceptual confusions cause Corbynismo to get crucial matters completely wrong.","translation":"三个概念上的混淆让科尔宾主义完全弄错了关键点。","targetForm":"confusions","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Every function should have comments describing its purpose in order to avoid confusion.","translation":"每一个函数都应该有描述其目的的注释以避免误解。","targetForm":"confusion","senseId":"source-n-2","sourceSenseId":"n-2"}]},"courage":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"勇气"}],"examples":[{"sentence":"If confidence, determination and courage are together in one place, there is nothing that cannot be done.","translation":"信心、毅力、勇气三者具备，则天下没有做不成的事。","targetForm":"courage","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Confidence and courage are not exclusively masculine traits—they are values that everyone can aspire to.","translation":"自信与勇气不仅是男性特质，也可以是所有人都能追求的价值。","targetForm":"courage","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Tom told Mary that he was going to kill himself, but he didn't have the courage to do it.","translation":"汤姆告诉玛丽他想要自杀，但他没有那么做的勇气。","targetForm":"courage","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Despite me wanting to go to this place for a long time, I never had the courage to actualize my dream.","translation":"尽管我已经想去这个地方好久了，但从来没勇气实现自己的愿望。","targetForm":"courage","senseId":"source-n-1","sourceSenseId":"n-1"}]},"correspond":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"符合"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"通信"}],"examples":[{"sentence":"The figures correspond closely to the results reported by the independent research team.","translation":"这些数字与独立研究团队报告的结果非常符合。","targetForm":"correspond","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Each colour on the map corresponds to a different type of land use in the area.","translation":"地图上的每种颜色对应该地区一种不同的土地使用类型。","targetForm":"corresponds","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The students corresponded with a school abroad to compare how young people use public libraries.","translation":"学生与一所海外学校通信，比较年轻人如何使用公共图书馆。","targetForm":"corresponded","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Before printing the labels, check that every code corresponds with the correct storage box.","translation":"打印标签前，请检查每个代码是否与正确的储存箱对应。","targetForm":"corresponds","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"For years, the two historians corresponded about documents held in archives on opposite sides of the country.","translation":"多年来，两位历史学家就分别保存在国家两端档案馆中的文件通信。","targetForm":"corresponded","senseId":"source-v-2","sourceSenseId":"v-2"}]},"complication":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"复杂情况"}],"examples":[{"sentence":"The emergence of a third gender has added legal and administrative complications, creating unnecessary burdens.","translation":"第三性别的出现增加了法律和行政上的麻烦，徒增无谓的负担。","targetForm":"complications","senseId":"source-n-2","sourceSenseId":"n-2"}]},"course":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"课程"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"路线"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"一道菜"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"过程"}],"examples":[{"sentence":"The course combines short lectures with practical workshops where students apply each new idea.","translation":"这门课程把短讲座与实践研讨会结合起来，让学生应用每个新观点。","targetForm":"course","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The river changed its course after several years of heavy rain and erosion along the banks.","translation":"河流在多年暴雨和河岸侵蚀后改变了流向。","targetForm":"course","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The first course was served after everyone had arrived and found a seat at the long table.","translation":"所有人到齐并在长桌旁找到座位后，第一道菜端上来了。","targetForm":"course","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"Over the course of the project, the team learned that early consultation prevented later confusion.","translation":"在项目过程中，团队认识到早期咨询能防止后续混乱。","targetForm":"course","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The course of the discussion changed when a resident introduced new evidence about the site.","translation":"一名居民提出有关该地点的新证据后，讨论的走向发生了变化。","targetForm":"course","senseId":"source-n-2","sourceSenseId":"n-2"}]},"conflict":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"冲突"}],"examples":[{"sentence":"Sixty years later, the Arab-Israeli conflict reminds us that the Jews’ journey back to history continues.","translation":"六十年之后，阿拉伯—以色列冲突提醒着我们犹太人重返历史的征程仍在继续。","targetForm":"conflict","senseId":"source-n-2","sourceSenseId":"n-2"}]},"convert":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"改变宗教信仰者"}],"examples":[{"sentence":"The cells have the capacity to convert food into energy.","translation":"细胞具有将食物转化为能量的能力。","targetForm":"convert","senseId":"source-n-2","sourceSenseId":"n-2"}]},"cover":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"封面"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"盖子"}],"examples":[{"sentence":"The short list covers a lot of ground; what connects the targets is the amount of good they will do for people, the planet, and prosperity.","translation":"这份重点清单涉及到众多领域；其中的联系是能为民众、地球和繁荣带来多少好处。","targetForm":"covers","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The Pacific Ocean alone covers an area larger than that of all continents put together.","translation":"仅太平洋的面积就比所有的大陆的总和面积还要大。","targetForm":"covers","senseId":"source-n-1","sourceSenseId":"n-1"}]},"controversial":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"争论的"}],"examples":[{"sentence":"But this change will raise challenging social and political questions as well, particularly concerning privacy preferences and health care – both already controversial issues.","translation":"但相关变化同样会引发社会政治难题，尤其是在已经争议颇多的隐私偏好和医疗保健领域。","targetForm":"controversial","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"continent":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"大陆"}],"examples":[{"sentence":"ADDIS ABABA – Climate change will hit Africa – a continent that has contributed virtually nothing to bring it about – first and hardest.","translation":"亚的斯亚贝巴 — — 气候变化最先、也最沉重地打击了非洲这块从未造成过气候变化的大陆。","targetForm":"continent","senseId":"source-n-1","sourceSenseId":"n-1"}]},"company":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"公司"}],"examples":[{"sentence":"And, third, laws intended to protect private information should be reevaluated to ensure that IT companies are unable to profit from exploiting and manipulating it.","translation":"最重要的是，公众必须更加深刻地理解IT的经济效应，特别是改善了如此多的人的生活的技术如何只让如此少的人致富。","targetForm":"companies","senseId":"source-n-1","sourceSenseId":"n-1"}]},"concentration":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"集中"}],"examples":[{"sentence":"Housing prices in Hsinchu City have risen sharply due to the concentration of the tech industry.","translation":"新竹市区的房价因为科技产业聚集而水涨船高。","targetForm":"concentration","senseId":"source-n-1","sourceSenseId":"n-1"}]},"coat":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"外套"}],"examples":[{"sentence":"Mary asked whose coat it was and I told her it was mine.","translation":"玛丽问我这是谁的外套，我告诉她这是我的。","targetForm":"coat","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"That coat may have cost a lot of money, but it's worth it.","translation":"那件大衣可能需要很多钱，但它值得。","targetForm":"coat","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"I'm going to get my house a fresh coat of paint.","translation":"我要粉刷我的房子。","targetForm":"coat","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"There were a hat and a coat on the wall.","translation":"墙上挂着一顶帽子和一件大衣。","targetForm":"coat","senseId":"source-n-1","sourceSenseId":"n-1"}]},"consequence":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"重要性"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"后果","contextReviewed":true}],"examples":[{"sentence":"And that is what we are doing, as action on three issues of historic consequence demonstrates.","translation":"正如颇具历史意义的行动所表明的那样，这正是我们行动的目标。","targetForm":"consequence","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Unless all of us do so, the consequences will spare none of us.","translation":"除非我们都动员起来，否则后果不会放过任何人。","targetForm":"consequences","senseId":"source-n-4","sourceSenseId":"n-4"}]},"consistent":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"一致的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"坚持的"}],"examples":[{"sentence":"The results are consistent with earlier studies, although the new sample includes more rural residents.","translation":"结果与早期研究一致，尽管新样本包含更多农村居民。","targetForm":"consistent","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Consistent practice is more effective than studying for many hours only on the day before an exam.","translation":"持续练习比只在考试前一天学习很多小时更有效。","targetForm":"consistent","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"The guide uses consistent terms so that readers do not confuse similar stages of the process.","translation":"这份指南使用一致术语，避免读者混淆过程中的相似阶段。","targetForm":"consistent","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Her explanation was consistent, and every part matched the evidence recorded in the original notes.","translation":"她的解释前后一致，每部分都与原始笔记中的证据相符。","targetForm":"consistent","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"A consistent approach to marking helps students understand why one answer is stronger than another.","translation":"一致的评分方法帮助学生理解为什么一个答案比另一个更好。","targetForm":"consistent","senseId":"source-adj-2","sourceSenseId":"adj-2"}]},"committee":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"委员会"}],"examples":[{"sentence":"Only when the Party Committee Secretary came in person to resolve it was this point of view dispelled entirely.","translation":"直到党委书记出面加以解释，才算打消了这种想法。","targetForm":"committee","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"We need at least one policymaker on the committee to provide the perspective of someone who can help make decisions about the research.","translation":"我们需要至少一个关于委员会的政策制定者，提供有助于做出关于该研究的决策者观点。","targetForm":"committee","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"As figures from the National Development and Reform Committee show, the Internet has developed rapidly in rural China.","translation":"来自国家发展和改革委员会的数据显示，互联网在中国农村地区发展迅猛。","targetForm":"committee","senseId":"source-n-1","sourceSenseId":"n-1"}]},"color":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"颜色"}],"examples":[{"sentence":"No matter where you go, the sky will always be the same color.","translation":"不管你去哪里，天空都是同样的颜色。","targetForm":"color","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The color of her dress and that of her shoes go well together.","translation":"她裙子和鞋子的颜色很配。","targetForm":"color","senseId":"source-n-1","sourceSenseId":"n-1"}]},"concede":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"退让"}],"examples":[{"sentence":"England’s goalkeeper was criticized for the amount of goals he conceded.","translation":"英格兰的守门员因为自己失球过多而被批评。","targetForm":"conceded","senseId":"source-v-2","sourceSenseId":"v-2"}]}}};
